-- Harmony Lifestyle Academy — Wellness Module Content Seed
-- GENERATED by scripts/build-module-content-seed.mjs from content/modules/*.json.
-- Do not edit by hand: change the JSON, then regenerate.
--
-- Run supabase/module_content_schema.sql first. This file is idempotent: it
-- upserts every row, so re-running it publishes edited content.
-- 8 modules, 39 topics, 117 quiz questions
-- ═══════════════════════════════════════════════════════════════════
BEGIN;

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, icon = EXCLUDED.icon, description = EXCLUDED.description,
  audience = EXCLUDED.audience, sort_order = EXCLUDED.sort_order, updated_at = NOW();

ON CONFLICT (id) DO UPDATE SET
  module_id = EXCLUDED.module_id, slug = EXCLUDED.slug, title = EXCLUDED.title, icon = EXCLUDED.icon,
  summary = EXCLUDED.summary, objectives = EXCLUDED.objectives, duration_minutes = EXCLUDED.duration_minutes,
  xp_reward = EXCLUDED.xp_reward, lesson = EXCLUDED.lesson, reflection = EXCLUDED.reflection,
  faith_lens = EXCLUDED.faith_lens, sort_order = EXCLUDED.sort_order, updated_at = NOW();

-- Replace the questions of every seeded topic so that removed questions do not linger.
DELETE FROM public.module_quiz_questions
WHERE topic_id IN ('physical/nutrition-and-diet', 'physical/exercise-and-fitness', 'physical/sleep-hygiene', 'physical/medical-health', 'physical/personal-safety', 'social/communication-skills', 'social/relationship-building', 'social/community-involvement', 'social/networking-and-etiquette', 'social/conflict-resolution', 'intellectual/lifelong-learning', 'intellectual/critical-thinking', 'intellectual/creativity-and-innovation', 'intellectual/cognitive-skills', 'intellectual/cultural-awareness', 'emotional/emotional-intelligence', 'emotional/stress-management', 'emotional/coping-mechanisms', 'emotional/building-resilience', 'emotional/positive-psychology', 'environmental/sustainable-living', 'environmental/conservation-efforts', 'environmental/appreciation-of-nature', 'environmental/healthy-personal-space', 'environmental/community-green-initiatives', 'vocational/career-exploration', 'vocational/skill-development', 'vocational/work-life-balance', 'vocational/financial-literacy', 'vocational/entrepreneurship', 'spiritual/presence', 'spiritual/gratitude', 'spiritual/purpose', 'spiritual/resilience', 'spiritual-islamic/dhikr-and-remembrance', 'spiritual-islamic/dua-and-supplication', 'spiritual-islamic/tawakkul-and-trust-in-allah', 'spiritual-islamic/gratitude-shukr', 'spiritual-islamic/prayer-and-devotion');


COMMIT;

