INSERT INTO public.wellness_modules (id, name, icon, description, audience, sort_order)
VALUES
('physical', 'Physical Wellness', '💪', 'Build the daily habits that keep your body strong, rested and safe: food, movement, sleep, health care and personal safety.', 'universal', 1),
('social', 'Social Wellness', '🤝', 'Learn to listen, speak, connect and disagree well, so that your relationships with family, friends and community grow stronger.', 'universal', 2),
('intellectual', 'Intellectual Wellness', '🧠', 'Train your mind to keep learning, think clearly, create new ideas and understand people who see the world differently.', 'universal', 3),
('emotional', 'Emotional Wellness', '💖', 'Understand what you feel and why, manage stress and setbacks, and build the habits that support a steady, hopeful mind.', 'universal', 4),
('environmental', 'Environmental Wellness', '🌿', 'Care for the places that care for you: your room, your neighbourhood and the natural world you depend on.', 'universal', 5),
('vocational', 'Vocational Wellness', '🧭', 'Find work that fits you, build the skills it needs, handle money wisely and keep your life in balance while you do it.', 'universal', 6),
('spiritual', 'Spiritual Wellness', '🧘', 'Secular mindfulness pathways: train your attention, appreciate what you have, live by your values and recover your balance when life is hard.', 'universal', 7),
('spiritual-islamic', 'Islamic Spiritual Wellness', '🕌', 'Strengthen your connection with Allah through remembrance, supplication, trust, gratitude and prayer, grounded in the Quran and the authentic Sunnah.', 'muslim', 8)
INSERT INTO public.module_topics
  (id, module_id, slug, title, icon, summary, objectives, duration_minutes, xp_reward, lesson, reflection, faith_lens, sort_order)
VALUES
('physical/nutrition-and-diet', 'physical', 'nutrition-and-diet', 'Nutrition & Diet', '🍎', 'How to build a balanced plate, read what your body needs, and eat well on a student budget.', '["Describe what carbohydrates, protein, fats, fibre and water each do for your body.","Build a balanced meal using the Malaysian Healthy Plate (Suku-Suku Separuh).","Spot hidden sugar in everyday drinks and snacks."]'::jsonb, 12, 20, '{"title":"Fuel, Not Just Food","explanation":"Everything you eat does a job. Carbohydrates (rice, bread, noodles, fruit) are your main energy source. Protein (fish, chicken, eggs, tempeh, beans) builds and repairs muscle, skin and blood. Fats (nuts, fish, cooking oil) carry certain vitamins and protect your organs. Fibre keeps digestion moving and keeps you full, and water does almost everything else, from cooling you down to helping you concentrate.\n\nYou do not need a complicated diet to get these in the right amounts. The Ministry of Health Malaysia teaches a simple picture called Suku-Suku Separuh: fill a quarter of your plate with rice or another grain, a quarter with protein, and half with vegetables and fruit. Choose plain water as your default drink.\n\nThe usual problem for young people is not too little food but too much sugar, salt and deep-fried food hiding in drinks and snacks. The World Health Organization advises keeping added sugar below 10% of your daily energy, and ideally below about 6 teaspoons a day. A single bubble tea or canned drink can use up most of that limit.","keyPoints":["Each food group has a different job, so variety matters more than any single ''superfood''.","Suku-Suku Separuh: a quarter grains, a quarter protein, half vegetables and fruit.","Sugary drinks are the easiest place to cut excess sugar without eating less food.","Regular meals, especially breakfast, support steady energy and concentration in class."],"examples":[{"title":"Fixing a mamak order","scenario":"Aiman usually orders nasi goreng with a fried egg and teh ais. The plate is almost all carbohydrate and oil, with no vegetables, and the drink adds several teaspoons of sugar.","takeaway":"He keeps the meal he likes but changes three things: a smaller rice portion, a side of vegetables or ulam, and teh o kosong or water. Same stall, far better balance."},{"title":"Reading a drink label","scenario":"Mei Ling checks the label on her favourite 500 ml bottled tea and finds 35 g of sugar. One teaspoon is about 4 g, so the bottle holds almost 9 teaspoons.","takeaway":"Dividing the grams of sugar by 4 turns a label into teaspoons you can picture. That one bottle is already over the ideal daily limit."}],"practicalTip":"For the next three days, take a photo of every meal before you eat it. At the end, check each photo against Suku-Suku Separuh and pick the one change that would be easiest to make.","deeperInsight":"Hunger and fullness signals reach your brain slowly, roughly 15 to 20 minutes after you start eating. Eating fast or while scrolling makes it easy to overshoot. Slowing down is one of the few nutrition habits that costs nothing and needs no willpower over what is on the plate."}'::jsonb, '{"prompt":"Think about what you ate yesterday. Which meal was closest to a balanced plate, and which was furthest?","guidingQuestions":["What usually decides what you eat: hunger, habit, price, or what friends are having?","Which sugary drink could you swap for water this week?","How do you feel in class after a heavy, oily lunch compared with a lighter one?"]}'::jsonb, '{"text":"The Quran joins eating with moderation in a single command: eat and drink, but do not be excessive. The Prophet ﷺ gave that a practical measure, describing a few mouthfuls as enough, and if more is needed, a third for food, a third for drink and a third for breath. Eating halal and good food in moderation is an act of gratitude for the body Allah has entrusted to you.","sources":["Quran 7:31","Quran 2:168","Jami'' at-Tirmidhi 2380 (hasan sahih)"]}'::jsonb, 1),
('physical/exercise-and-fitness', 'physical', 'exercise-and-fitness', 'Exercise & Fitness', '💪', 'How much movement your body needs each week and how to build a routine you will actually keep.', '["State the World Health Organization activity guidelines for your age group.","Tell apart aerobic, strength and flexibility training and why each matters.","Plan a realistic weekly routine using small, consistent sessions."]'::jsonb, 12, 20, '{"title":"Move Often, Not Just Hard","explanation":"Your body is built to move, and it adapts to whatever you regularly ask of it. Aerobic activity (brisk walking, cycling, futsal, swimming) trains your heart and lungs. Strength work (push-ups, squats, carrying, climbing) builds muscle and bone. Flexibility and balance work keeps joints moving freely and reduces injury.\n\nThe World Health Organization recommends that young people aged 5 to 17 average at least 60 minutes a day of moderate-to-vigorous activity, with muscle- and bone-strengthening activity on at least 3 days a week. Adults need 150 to 300 minutes of moderate activity a week, or 75 to 150 minutes of vigorous activity, plus strength training on 2 or more days.\n\nA useful test of intensity is the talk test. At moderate intensity you can talk but not sing. At vigorous intensity you can only say a few words before needing a breath. Minutes add up across the day, so walking to school, taking stairs and a short evening workout all count. Consistency beats intensity: four 20-minute sessions a week will do more for you than one exhausting session a month.","keyPoints":["Ages 5 to 17: an average of 60 minutes a day; adults: at least 150 minutes of moderate activity a week.","A complete routine includes aerobic, strength and flexibility work.","Use the talk test to judge intensity without any equipment.","Short, regular sessions build fitness more reliably than rare, intense ones."],"examples":[{"title":"No gym, no problem","scenario":"Farah has no gym membership and little free time. She does a 15-minute circuit in her room three mornings a week: squats, wall push-ups, a plank and jumping jacks, and she walks 20 minutes home from school.","takeaway":"Bodyweight exercise plus everyday walking covers both strength and aerobic needs. The plan works because it fits into time she already has."},{"title":"The weekend warrior","scenario":"Daniel sits most of the week, then plays two hours of hard futsal on Sunday and is sore until Wednesday.","takeaway":"Spreading activity through the week, even 20 minutes on three weekdays, would reduce his soreness and injury risk and make Sunday''s game more enjoyable."}],"practicalTip":"Attach movement to something you already do. For example: ten squats after brushing your teeth each morning, or a 10-minute walk straight after Asar or after dinner. An existing habit is the most reliable reminder.","deeperInsight":"Exercise changes your brain as well as your muscles. Physical activity increases blood flow to the brain and is linked with better mood, sleep and attention. Many students cut exercise during exam season to save time, when a short session is one of the more effective ways to study better afterwards."}'::jsonb, '{"prompt":"Look back over the last seven days. On how many of them did you move enough to get slightly out of breath?","guidingQuestions":["What activity do you enjoy enough to do even when you are not being told to?","What usually stops you from exercising: time, energy, space, or shyness?","Which existing daily habit could you attach ten minutes of movement to?"]}'::jsonb, '{"text":"The Prophet ﷺ said that the strong believer is better and more beloved to Allah than the weak believer, while there is good in both. Strength here includes strength of faith and resolve, and scholars also apply it to a body that is fit to worship, work and help others. Looking after your fitness with that intention turns exercise into worship.","sources":["Sahih Muslim 2664"]}'::jsonb, 2),
('physical/sleep-hygiene', 'physical', 'sleep-hygiene', 'Sleep Hygiene', '😴', 'Why sleep is active recovery, how much you need, and the habits that make falling asleep easier.', '["State how many hours of sleep teenagers and young adults need.","Explain how light, caffeine and irregular timing disrupt sleep.","Design a wind-down routine for the last hour before bed."]'::jsonb, 10, 20, '{"title":"Sleep Is When the Work Gets Saved","explanation":"Sleep is not switched-off time. While you sleep, your brain sorts the day''s learning into long-term memory, your body repairs tissue and releases growth hormone, and your immune system resets. Teenagers aged 13 to 18 need about 8 to 10 hours a night, and young adults need 7 to 9.\n\nYour body runs on an internal clock of roughly 24 hours called the circadian rhythm. Light is its main signal. Bright light in the morning tells the clock the day has started. Bright light at night, especially from a phone held close to your face, delays the release of melatonin, the hormone that makes you sleepy. Caffeine works differently: it blocks the brain''s sleepiness signal, and about half of it is still in your body five to six hours after you drink it.\n\nSleep hygiene means the habits that protect sleep. The most powerful one is regular timing: going to bed and waking at about the same time every day, including weekends. Next are a cool, dark, quiet room, no caffeine after mid-afternoon, and a screen-free wind-down before bed.","keyPoints":["Teenagers need 8 to 10 hours; young adults need 7 to 9.","Sleep is when memories are consolidated, so cutting sleep to study works against you.","A consistent wake-up time is the strongest anchor for your body clock.","Screens and caffeine late in the day both delay sleep, by different mechanisms."],"examples":[{"title":"The all-nighter that backfired","scenario":"Before a Sejarah exam, Hakim studies until 4 a.m. and sleeps two hours. In the exam hall he recognises the questions but cannot recall the details he read at 2 a.m.","takeaway":"Material studied without sleep afterwards is poorly stored. Stopping at 11 p.m. and sleeping would have kept more of what he learned."},{"title":"Weekend jet lag","scenario":"Priya wakes at 6 a.m. on school days but sleeps until noon on Saturday and Sunday. Every Monday she feels as if she has flown across time zones.","takeaway":"Shifting wake time by several hours confuses the body clock. Keeping weekend wake-ups within about an hour of weekdays removes the Monday crash."}],"practicalTip":"Set a ''phone bedtime'' alarm 45 minutes before you plan to sleep. When it rings, put the phone to charge outside arm''s reach, then shower, prepare tomorrow''s bag, or read something on paper.","deeperInsight":"During puberty the body clock naturally shifts later, so teenagers really do feel sleepy later at night than children or adults. You cannot remove the shift, but morning daylight and a fixed wake time pull the clock earlier, while late-night screens push it later still."}'::jsonb, '{"prompt":"What did the last hour before you slept look like last night?","guidingQuestions":["How many hours do you actually sleep on a school night?","What is the last thing you look at before closing your eyes?","What one change to your evening would be easiest to try for a week?"]}'::jsonb, '{"text":"The Quran describes sleep as a mercy: Allah made the night a covering and sleep a means of rest. The Prophet ﷺ disliked sleeping before the Isha prayer and staying up in conversation after it, a pattern of early sleep and early rising that matches what we now know about the body clock. He also taught making wudu'' before bed and sleeping on the right side.","sources":["Quran 78:9-11","Quran 25:47","Sahih al-Bukhari 568","Sahih al-Bukhari 247"]}'::jsonb, 3),
('physical/medical-health', 'physical', 'medical-health', 'Medical Health', '🩺', 'Knowing your body, using health services wisely, and recognising when to get help.', '["Explain why prevention and early detection matter even when you feel well.","Recognise warning signs that need a doctor or emergency care.","Judge whether a piece of online health information is reliable."]'::jsonb, 12, 20, '{"title":"Be the First Expert on Your Own Body","explanation":"Good medical health starts before you are sick. Prevention includes vaccinations, dental check-ups, eye tests, hand washing and knowing your family''s health history. Early detection means noticing changes and getting them checked while they are still small and easy to treat.\n\nLearn what is normal for you: your usual energy, sleep, appetite, weight and mood. A change that lasts more than about two weeks, such as constant tiredness, unexplained weight change, a persistent cough or a low mood that does not lift, is worth showing to a doctor. Some signs should never wait: chest pain, difficulty breathing, fainting, severe bleeding, a severe allergic reaction, or thoughts of harming yourself. In Malaysia, call 999 in an emergency.\n\nUse medicines exactly as directed. Antibiotics treat bacterial infections only. They do nothing for colds and flu, which are caused by viruses, and misusing them helps bacteria become resistant. Be careful with health advice online. Check who is giving it, whether they are qualified, and whether they are selling something. Mental health is part of medical health, and asking for help with it is as reasonable as seeing a doctor for a broken arm.","keyPoints":["Prevention and early detection are easier and cheaper than treatment.","Know your own baseline so that you notice changes.","Chest pain, breathing difficulty, fainting, severe bleeding and thoughts of self-harm need urgent help: call 999.","Antibiotics do not work on viral illnesses such as colds and flu."],"examples":[{"title":"The headache that was eyesight","scenario":"Siti gets a headache most afternoons and takes paracetamol every day for a month. A school nurse suggests an eye test, which shows she needs glasses.","takeaway":"A symptom that keeps returning is a message. Treating the cause is better than silencing the signal again and again."},{"title":"The viral remedy","scenario":"A video claims a herbal drink ''cures diabetes in 7 days'' and links to a shop. Arjun''s uncle wants to stop his prescribed medicine and try it.","takeaway":"A dramatic cure, no named medical source and a product for sale are three red flags. Arjun suggests his uncle ask the clinic pharmacist before changing anything."}],"practicalTip":"Create a short health note on your phone: blood type if known, allergies, regular medicines, vaccination record, and an emergency contact. It takes ten minutes and can save crucial time in a clinic or emergency.","deeperInsight":"Many adult illnesses, including type 2 diabetes and heart disease, develop silently over years and are shaped by habits formed in the teens and twenties. That is why a person who feels perfectly healthy at 17 still benefits from good sleep, food and activity now."}'::jsonb, '{"prompt":"When did you last have a health check of any kind: dental, eyes, or a general check-up?","guidingQuestions":["Is there a small symptom you have been ignoring for more than two weeks?","Who would you talk to first if you were worried about your physical or mental health?","Where do you usually get health information, and how do you know it is reliable?"]}'::jsonb, '{"text":"The Prophet ﷺ taught that Allah has not sent down any disease without also sending down its cure. Seeking treatment is therefore part of trusting Allah, not a contradiction of it. Your body is an amanah, a trust, and caring for it with proper medical help is a way of honouring that trust.","sources":["Sahih al-Bukhari 5678","Sahih Muslim 2204"]}'::jsonb, 4),
('physical/personal-safety', 'physical', 'personal-safety', 'Personal Safety', '🛡️', 'Awareness, boundaries and simple plans that keep you safe in public, at home and online.', '["Practise situational awareness in everyday places.","Set and state a personal boundary clearly.","Recognise common online scams and know where to report them."]'::jsonb, 12, 20, '{"title":"Aware, Not Afraid","explanation":"Personal safety is mostly about prevention. The goal is to notice risk early and leave before a situation becomes dangerous, not to win a fight. Situational awareness means keeping part of your attention on your surroundings: who is nearby, where the exits are, and whether anything feels wrong. Walking with both earphones in and your eyes on your phone removes that awareness.\n\nTrust your instincts. If a person or place makes you uneasy, you do not need proof before you move away, call someone or say no. A boundary is a clear statement of what you will not accept, such as ''Stop. I am not comfortable with that.'' You do not owe anyone an apology for protecting yourself. If you are ever in danger, the order of priority is: get away, get to people, get help. Belongings can be replaced.\n\nOnline safety follows the same logic. Scammers create urgency (''act now or your account will be closed''), pretend to be an authority, and ask for passwords, TAC codes or money. No bank or government agency will ask for your password or TAC by phone or message. In Malaysia, call the National Scam Response Centre on 997 if money has been transferred, and 999 for emergencies.","keyPoints":["Prevention and early exit are safer than confrontation.","Keep your attention up in transit: one earphone out, phone away, know your exits.","You can set a boundary without explaining or apologising.","Urgency plus a request for codes, passwords or money is the pattern of a scam."],"examples":[{"title":"The walk home","scenario":"Walking home at dusk, Nadia notices the same motorcycle pass her slowly twice. She crosses the road, walks into a busy kedai runcit and calls her mother to come and meet her.","takeaway":"She acted on a pattern, not on certainty. Moving towards people and light and telling someone are simple, effective responses."},{"title":"The ''bank officer'' call","scenario":"Wei Jie gets a call saying his account is frozen and he must read out the six-digit code just sent to his phone to unlock it.","takeaway":"Urgency, claimed authority and a request for a code are the classic combination. He hangs up and calls the number printed on his bank card instead."}],"practicalTip":"Agree a code word with your family or a close friend. Sending or saying that word means ''I need you to call me or come and get me now'', with no questions asked until you are safe.","deeperInsight":"Most harm to young people comes from someone they already know, not from strangers. Safety skills therefore include recognising when someone familiar is pressuring you, isolating you from friends or asking you to keep secrets, and telling a trusted adult when that happens."}'::jsonb, '{"prompt":"Picture your usual route to school, work or the shops. Where on that route are you least aware of your surroundings?","guidingQuestions":["Who are the two people you would contact first if you felt unsafe?","Have you ever ignored an uneasy feeling? What happened?","Which of your online accounts would cause the most damage if someone else got in?"]}'::jsonb, '{"text":"The Quran instructs believers not to throw themselves into destruction by their own hands, and to do good. When a man asked whether he should tie his camel or leave it and rely on Allah, the Prophet ﷺ answered: tie it, and rely on Allah. Taking sensible precautions is part of tawakkul, not a lack of it.","sources":["Quran 2:195","Jami'' at-Tirmidhi 2517 (hasan)"]}'::jsonb, 5),
('social/communication-skills', 'social', 'communication-skills', 'Communication Skills', '💬', 'Listening so people feel heard, and speaking so that your meaning arrives intact.', '["Use the three steps of active listening in a real conversation.","Turn a blaming ''you'' statement into a clear ''I'' statement.","Explain how tone and body language change the meaning of words."]'::jsonb, 12, 20, '{"title":"Heard Before Being Understood","explanation":"Communication has two halves, and most people practise only one of them. Speaking gets the attention, but listening does most of the work. Active listening has three steps. First, give full attention: phone down, eyes up. Second, reflect back what you heard in your own words (''So you felt left out when we went without you?''). Third, ask before advising (''Do you want ideas, or do you just want me to listen?''). People who feel heard become far more willing to hear you in return.\n\nWhen it is your turn to speak, be clear and own your message. A ''you'' statement such as ''You never listen to me'' sounds like an attack and invites defence. An ''I'' statement describes the situation, your feeling and your request: ''When I am interrupted, I feel unimportant. Could you let me finish?'' It is harder to argue with and easier to act on.\n\nWords carry only part of the message. Tone of voice, facial expression and posture tell the listener how to interpret what you say. Saying ''I''m fine'' with folded arms and a flat voice sends two messages, and people believe the body. In text messages, where tone is missing, misunderstandings multiply, so save important or emotional conversations for a call or face to face.","keyPoints":["Active listening: attend fully, reflect back, ask before advising.","''I'' statements describe your experience and make a request without blame.","When words and body language disagree, people trust the body language.","Text removes tone, so use voice or face-to-face talk for sensitive topics."],"examples":[{"title":"Group project tension","scenario":"Haziq is frustrated that a teammate keeps missing deadlines. His first draft message says, ''You are so lazy, you always let us down.''","takeaway":"He rewrites it: ''When the slides come in late, I get stressed because I can''t finish my part. Can we agree on Thursday night as the deadline?'' The teammate replies with an apology and a plan instead of an argument."},{"title":"Listening to a friend","scenario":"Amira''s friend says she failed her driving test again. Amira is about to list tips, but pauses and says, ''That sounds really disappointing after all that practice. Do you want to talk about it?''","takeaway":"Reflecting the feeling first lets the friend feel understood. Advice offered later, when asked for, is much more likely to be welcome."}],"practicalTip":"In your next conversation, try the two-second rule: after the other person stops talking, wait two full seconds before you reply. It stops you interrupting and gives you time to respond to what they said.","deeperInsight":"You may have heard that ''93% of communication is non-verbal''. That figure comes from small 1960s experiments by Albert Mehrabian about conveying feelings with single words, and he has said it should not be applied to communication in general. The safer lesson is that tone and body language matter most when they contradict your words."}'::jsonb, '{"prompt":"Recall a recent conversation that went badly. At what moment did it start to go wrong?","guidingQuestions":["Were you listening to understand, or waiting for your turn to speak?","How would you rewrite one thing you said as an ''I'' statement?","Who in your life makes you feel truly heard, and what do they do?"]}'::jsonb, '{"text":"Allah commands believers to speak to people with good words, and the Prophet ﷺ gave a simple filter for every sentence: whoever believes in Allah and the Last Day should speak good or remain silent. He was also known to turn his whole body towards the person speaking to him, giving full attention. Careful speech and real listening are part of faith.","sources":["Quran 2:83","Quran 17:53","Sahih al-Bukhari 6018","Sahih Muslim 47"]}'::jsonb, 1),
('social/relationship-building', 'social', 'relationship-building', 'Relationship Building', '🤝', 'What makes a relationship healthy, how trust is built, and how to recognise one that is harming you.', '["Name the qualities of a healthy relationship.","Explain how small, repeated actions build or erode trust.","Identify warning signs of an unhealthy or controlling relationship."]'::jsonb, 12, 20, '{"title":"Trust Is Built in Small Moments","explanation":"Healthy relationships, whether with family, friends or a future spouse, share the same foundations: respect, honesty, trust, support and room for each person to be themselves. You feel safe to disagree, and you can say no without fear of punishment.\n\nTrust rarely comes from grand gestures. It builds through many small moments: replying when you said you would, keeping a secret, turning up, noticing when someone is quiet and asking why. Each one is like a small deposit in a shared account. Broken promises, gossip and being ignored are withdrawals. Relationship researcher John Gottman found that stable couples had about five positive interactions for every negative one during conflict, and the same idea is useful for friendships: the everyday balance matters more than any single event.\n\nIt is equally important to recognise what is unhealthy. Warning signs include someone who controls who you see, checks your phone, mocks you in front of others, makes you feel guilty for having other friends, or is kind only when they want something. A relationship should make your world larger, not smaller. Ending or stepping back from a harmful relationship is a healthy choice, and a trusted adult can help you do it safely.","keyPoints":["Respect, honesty, trust, support and freedom to be yourself mark a healthy relationship.","Trust grows from small promises kept consistently.","Positive moments need to clearly outnumber negative ones.","Control, isolation and humiliation are warning signs, even from someone you care about."],"examples":[{"title":"The reliable friend","scenario":"Jun Hao is not the loudest in his group, but he remembers exam dates, saves a seat, and checks in when someone is absent. When he needs help moving house, six friends show up.","takeaway":"Small, steady acts of care built a deep reserve of goodwill. Reliability is one of the strongest forms of friendship."},{"title":"The shrinking circle","scenario":"Since Alya became close to a new friend, she has stopped seeing her old group. The friend gets angry when Alya spends time with anyone else and insists on reading her messages.","takeaway":"Isolation and monitoring are signs of control, not closeness. Alya talks to her older sister, who helps her set limits and reconnect with her other friends."}],"practicalTip":"Choose one relationship that matters to you and make one small deposit today: send a message of thanks, ask a real question about their week, or keep a promise you have been putting off.","deeperInsight":"Family relationships change as you grow up. Moving from being told what to do towards being consulted takes negotiation on both sides. Showing responsibility in small things, and explaining your reasoning calmly, usually earns more freedom than arguing for it."}'::jsonb, '{"prompt":"Think of the person you trust most. What have they done, repeatedly, that earned that trust?","guidingQuestions":["Which of your relationships makes your world feel larger?","Is there one where you feel smaller or more anxious afterwards?","What small deposit could you make in a relationship you have neglected?"]}'::jsonb, '{"text":"The Prophet ﷺ set the standard for every relationship in one sentence: none of you truly believes until he loves for his brother what he loves for himself. He also taught that the best of people are those best to their families. Maintaining ties of kinship, being reliable and wanting good for others are acts of worship as well as social skills.","sources":["Sahih al-Bukhari 13","Sahih Muslim 45","Jami'' at-Tirmidhi 3895 (sahih)"]}'::jsonb, 2),
('social/community-involvement', 'social', 'community-involvement', 'Community Involvement', '🤗', 'Why contributing to your community benefits you as well as others, and how to start small.', '["Explain how volunteering benefits both the community and the volunteer.","Match your own skills and interests to a community need.","Plan a first, small act of service."]'::jsonb, 10, 20, '{"title":"You Belong Where You Contribute","explanation":"A community is any group that shares a place or a purpose: your neighbourhood, school, surau or temple, sports club or online group. Being involved means giving some of your time, skill or attention to make that shared space better.\n\nThe benefits run both ways. The community gains help it needs. The volunteer gains a sense of belonging and purpose, new friendships across ages and backgrounds, and real experience in teamwork, organising and leadership that classrooms rarely provide. Studies of volunteers consistently link regular helping with better mood and lower loneliness. Malaysians have a word for this spirit of shared work: gotong-royong.\n\nThe most common mistake is waiting for a big opportunity. Start with what you have. Ask three questions: What do I care about? What can I already do? What does my community need? The place where those answers overlap is your starting point. Someone who is good at maths can tutor younger children. Someone who likes cooking can help at a soup kitchen. Someone with a phone and patience can teach an elderly neighbour to make video calls. Small and regular is better than large and once.","keyPoints":["Community involvement means contributing time, skill or attention to a shared space.","Volunteers gain belonging, purpose, friendships and practical skills.","Start where your interests, your abilities and a real need overlap.","Regular small contributions have more effect than rare large ones."],"examples":[{"title":"Tuition under the stairs","scenario":"Kavitha notices primary pupils at her flat struggling with maths. She starts a free one-hour homework session every Saturday in the ground-floor common area. Two friends join her by the second month.","takeaway":"She matched a skill she already had to a visible need, and kept the commitment small enough to sustain. Others joined once it existed."},{"title":"The surau clean-up","scenario":"Irfan feels he has nothing to offer because he is ''not good at anything special''. He joins a monthly gotong-royong to clean the surau and ends up managing the volunteer list.","takeaway":"Showing up reveals abilities you did not know you had. Reliability and organisation are valuable skills in any community."}],"practicalTip":"This week, do one useful thing for your community that nobody asked you to do: pick up litter on your street, help carry a neighbour''s shopping, or offer an hour to a local group. Notice how you feel afterwards.","deeperInsight":"Helping works best when it respects the people being helped. Before starting a project, ask the community what it actually needs. Well-meaning projects designed without listening often solve the wrong problem."}'::jsonb, '{"prompt":"Which community do you feel most a part of, and what have you contributed to it so far?","guidingQuestions":["What problem in your neighbourhood or school bothers you most?","What can you already do that would be useful to someone else?","What stops you from getting involved, and how real is that barrier?"]}'::jsonb, '{"text":"Allah commands believers to cooperate in righteousness and piety. The Prophet ﷺ widened the idea of charity to include everyday service: every joint of a person owes a charity each day, and helping someone onto their mount, a good word, and removing something harmful from the road are all charity. Serving your community is a daily form of sadaqah.","sources":["Quran 5:2","Sahih al-Bukhari 2989","Sahih Muslim 1009"]}'::jsonb, 3),
('social/networking-and-etiquette', 'social', 'networking-and-etiquette', 'Networking & Etiquette', '🌐', 'Making real connections, introducing yourself with confidence, and showing respect in different settings.', '["Explain why networking is about relationships and not about using people.","Introduce yourself clearly in under thirty seconds.","Apply basic etiquette in person and in digital messages."]'::jsonb, 12, 20, '{"title":"Be Interested Before Being Interesting","explanation":"Networking simply means building relationships with people beyond your close circle: teachers, seniors, people in jobs you are curious about, and friends of friends. Many opportunities, including internships, advice and first jobs, travel through these connections. Sociologist Mark Granovetter showed that people often find jobs through ''weak ties'', acquaintances who move in different circles and therefore hear different information.\n\nGood networking is generous, not transactional. Be curious about the other person, listen more than you talk, and look for ways to be useful to them. A short self-introduction helps: your name, what you are doing now, and what you are curious about. For example, ''I''m Sofia, a Form 5 student interested in architecture. I''d love to know what your first year in the field was like.'' Follow up within a day or two with a brief thank-you message.\n\nEtiquette is how you show respect, and it varies by setting. In Malaysia this includes greeting elders first, using titles such as Encik, Puan, Dr or Cikgu until invited to do otherwise, and being punctual. Online, write to a teacher or employer with a greeting, a clear request, and your name. Do not send voice notes or late-night messages to people you do not know well. Remember that what you post publicly is part of how others meet you.","keyPoints":["Networking is relationship-building, and it works best when you give as well as ask.","Acquaintances (''weak ties'') often bring new information and opportunities.","A good introduction covers who you are, what you do and what you are curious about.","Etiquette means adapting your manners to show respect in each setting, including online."],"examples":[{"title":"The career-talk question","scenario":"After a school career talk, most students leave. Danish waits, thanks the speaker, asks one specific question about her engineering course, and later sends a two-line thank-you on LinkedIn.","takeaway":"A specific question and a prompt follow-up made him memorable. Months later she shares an internship posting with him."},{"title":"The message to a lecturer","scenario":"Li Ting first writes: ''hi when is the deadline??'' She rewrites it: ''Good morning Dr Rahman. I''m Li Ting from Tutorial Group 3. Could you confirm whether the report is due this Friday? Thank you.''","takeaway":"A greeting, context, a clear question and thanks take twenty extra seconds and completely change the impression."}],"practicalTip":"Write your thirty-second introduction now and say it aloud three times. Then send one short, polite message to someone whose work or study path interests you, asking a single specific question.","deeperInsight":"Many people avoid networking because it feels fake. The discomfort usually disappears when the aim changes from ''what can I get?'' to ''what can I learn, and how can I help?''. Students often underestimate what they can offer: a fresh perspective, energy, and help with tasks that seniors have no time for."}'::jsonb, '{"prompt":"Who is one person outside your close circle that you would like to learn from?","guidingQuestions":["What specific question would you ask them?","What could you offer in return, even something small?","If a stranger looked at your public social media today, what impression would they form?"]}'::jsonb, '{"text":"The Quran explains that humanity was made into peoples and tribes so that we may know one another, and that the most honoured are the most God-conscious. The Prophet ﷺ taught that spreading the greeting of salam builds love between people, and he greeted others first, including children. Good manners with everyone you meet are a mark of faith.","sources":["Quran 49:13","Sahih Muslim 54","Sahih al-Bukhari 6247"]}'::jsonb, 4),
('social/conflict-resolution', 'social', 'conflict-resolution', 'Conflict Resolution', '⚖️', 'Staying calm in a disagreement and finding solutions that both sides can accept.', '["Describe the five common styles of handling conflict.","Separate a person''s position from their underlying interest.","Follow a step-by-step process to resolve a disagreement."]'::jsonb, 12, 20, '{"title":"Attack the Problem, Not the Person","explanation":"Conflict is normal wherever people have different needs. Handled badly it damages relationships. Handled well it can improve them, because problems get solved and each side understands the other better.\n\nThe Thomas-Kilmann model describes five styles. Competing means pushing to win. Avoiding means staying away from the issue. Accommodating means giving in. Compromising means each side gives up something. Collaborating means working together for a solution that meets both sides'' main needs. No style is always right. Avoiding is sensible for trivial matters or when tempers are high, and collaborating is worth the effort when both the issue and the relationship matter.\n\nThe key to collaborating is to look beneath positions to interests. A position is what someone says they want (''I want the window open''). An interest is why (''I need fresh air''). Positions clash, but interests can often both be met. A practical process is: cool down first, since nobody thinks well when angry. Then let each person state their view without interruption. Name the interests on each side. Brainstorm options together. Agree on one and check later whether it is working.","keyPoints":["Conflict is normal; how it is handled decides whether it harms or helps.","Five styles: competing, avoiding, accommodating, compromising, collaborating.","Ask ''why?'' to move from positions to interests.","Cool down before talking, and focus on the problem instead of the person''s character."],"examples":[{"title":"The shared room","scenario":"Two sisters argue nightly. One wants the light off at 10 p.m. and the other wants it on to study. Their positions cannot both win.","takeaway":"Asking why reveals the interests: sleep and study time. A desk lamp and an eye mask meet both. The solution was invisible while they argued about the light switch."},{"title":"The group-chat blow-up","scenario":"Ravi feels insulted by a joke in the class group chat and starts typing an angry reply. He stops, waits an hour, then messages his classmate privately: ''That joke stung. Can we talk?''","takeaway":"Cooling down and moving the conversation from public to private stopped a small hurt becoming a class-wide fight."}],"practicalTip":"When you feel anger rising in a disagreement, say: ''I want to sort this out, but I need ten minutes first.'' Walk, drink water, breathe slowly, then return. A pause with a promise to come back is not avoidance.","deeperInsight":"Strong anger narrows attention and makes the other person look like an enemy. This is a body state as much as an opinion, and it passes. Most things said in the first heated minutes are regretted later, which is why the cooling-off step matters more than any clever wording."}'::jsonb, '{"prompt":"Think of a disagreement you are in now, or had recently. What does the other person actually need?","guidingQuestions":["Which of the five styles do you use most often, and does it serve you?","What is your position in that disagreement, and what is the interest beneath it?","What would a solution that works for both of you look like?"]}'::jsonb, '{"text":"The Quran calls the believers brothers and commands making peace between them, and it teaches repelling a wrong with what is better, so that an enemy may become a close friend. The Prophet ﷺ redefined strength itself: the strong person is not the one who overpowers others, but the one who controls himself when angry. Reconciling people is counted among the best of deeds.","sources":["Quran 49:10","Quran 41:34","Sahih al-Bukhari 6114","Sahih Muslim 2609"]}'::jsonb, 5),
('intellectual/lifelong-learning', 'intellectual', 'lifelong-learning', 'Lifelong Learning', '📚', 'How your brain keeps changing with practice, and how to learn anything more effectively.', '["Explain neuroplasticity and what it means for your ability to learn.","Contrast a growth mindset with a fixed mindset.","Use the Feynman technique to test your understanding of a topic."]'::jsonb, 12, 20, '{"title":"Your Brain Is Not Finished","explanation":"Learning does not end when school does. Your brain physically changes whenever you practise something: connections between nerve cells that are used repeatedly grow stronger, and unused ones weaken. This ability is called neuroplasticity, and it continues throughout life. A skill that feels impossible today is usually a skill you have not practised enough yet.\n\nPsychologist Carol Dweck describes two ways people think about ability. In a fixed mindset, talent is something you either have or lack, so mistakes feel like proof of failure and challenges are avoided. In a growth mindset, ability develops through effort, good strategies and feedback, so mistakes are information. The word ''yet'' captures the difference: ''I can''t do this'' becomes ''I can''t do this yet''.\n\nHow you study matters as much as how long. Re-reading notes feels productive but teaches little. A stronger method is the Feynman technique: choose a concept, explain it in simple words as if teaching a twelve-year-old, notice where you get stuck, go back to the source to fill that gap, then explain again. If you cannot explain it simply, you do not understand it yet. Curiosity keeps the whole process going, so follow the questions that interest you.","keyPoints":["Neuroplasticity: the brain strengthens whatever connections you use repeatedly, at any age.","A growth mindset treats mistakes as information, not as a verdict.","Explaining a concept in simple words exposes the gaps in your understanding.","Learning continues outside school through reading, courses, mentors and practice."],"examples":[{"title":"\"I''m just bad at maths\"","scenario":"After failing an Add Maths test, Hana says she is ''not a maths person''. Her teacher asks her to list which question types she lost marks on. Almost all are in one chapter.","takeaway":"The problem was one specific gap, not her brain. Naming the gap turned a fixed label into a task she could work on."},{"title":"Teaching to learn","scenario":"Zhi Wei thinks he understands photosynthesis until he tries to explain it to his younger brother and cannot say where the oxygen comes from.","takeaway":"Trying to teach revealed exactly what he did not know. Ten minutes with the textbook fixed a gap that re-reading had hidden."}],"practicalTip":"Pick one thing you are curious about that is not in any syllabus. Spend fifteen minutes a day on it for one week, then explain what you learned to someone at home.","deeperInsight":"Without review, people forget a large share of new information within days, a pattern first measured by Hermann Ebbinghaus in the 1880s. Each time you review, the memory fades more slowly. A little review spread over days therefore beats one long session."}'::jsonb, '{"prompt":"What is something you once could not do and now can? How did that change happen?","guidingQuestions":["Where in your life do you say ''I''m just not good at that''?","What would change if you added the word ''yet''?","What have you always wanted to learn, with no exam attached?"]}'::jsonb, '{"text":"The first word revealed of the Quran was ''Read'', and the only thing Allah told His Prophet ﷺ to ask for more of was knowledge: ''My Lord, increase me in knowledge.'' The Prophet ﷺ said that whoever travels a path seeking knowledge, Allah makes easy for him a path to Paradise. Learning, with the right intention, is worship from cradle to grave.","sources":["Quran 96:1-5","Quran 20:114","Sahih Muslim 2699"]}'::jsonb, 1),
('intellectual/critical-thinking', 'intellectual', 'critical-thinking', 'Critical Thinking', '🤔', 'Questioning claims, checking sources and catching your own biases before you believe or share.', '["Distinguish a claim from the evidence offered for it.","Recognise confirmation bias in your own thinking.","Apply the SIFT method to check information before sharing it."]'::jsonb, 12, 20, '{"title":"Slow Down Before You Share","explanation":"Critical thinking is the habit of asking ''How do we know that?'' before accepting a claim. It is not being negative or doubting everything. It means matching the strength of your belief to the strength of the evidence.\n\nStart by separating the claim from the evidence. ''This drink boosts immunity'' is a claim. Who tested it, on how many people, and compared with what? A personal story is weak evidence. A well-designed study is stronger. Agreement across many independent studies is stronger still. Notice also the difference between correlation and causation: two things happening together does not prove one caused the other.\n\nThe hardest part is your own mind. Confirmation bias is the tendency to notice and believe information that supports what you already think, and to dismiss what does not. Everyone has it. A useful check is to ask, ''What would change my mind?''\n\nFor online information, use SIFT, a method from digital literacy researcher Mike Caulfield. Stop before reacting or sharing. Investigate the source: who is behind it? Find better coverage: do reliable outlets report the same thing? Trace the claim, quote or image back to its original context. In Malaysia, sebenarnya.my can help verify viral claims.","keyPoints":["Ask what the evidence is, and how strong, before accepting a claim.","Correlation does not prove causation.","Confirmation bias makes agreeable information feel more true than it is.","SIFT: Stop, Investigate the source, Find better coverage, Trace to the original."],"examples":[{"title":"The forwarded warning","scenario":"A family WhatsApp group shares a message that a common fruit ''causes cancer according to doctors''. No doctor is named and there is no link. Nurul searches the claim and finds a Ministry of Health statement that it is false.","takeaway":"An unnamed authority and no source are warning signs. Thirty seconds of checking stopped the message at her instead of spreading through her contacts."},{"title":"Ice cream and drowning","scenario":"A chart shows that ice cream sales and drowning cases rise in the same months. A classmate jokes that ice cream causes drowning.","takeaway":"Both rise because of a third factor: hot weather brings more swimming and more ice cream. Always ask what else could explain a pattern."}],"practicalTip":"Before you forward or repost anything this week, apply one rule: if you cannot name the original source, do not share it. Notice how often that rule stops you.","deeperInsight":"Content designed to spread usually targets emotion, especially anger and fear, because strong feeling pushes people to share before thinking. If a post makes you feel a sudden rush of outrage, treat that feeling as a signal to slow down and check."}'::jsonb, '{"prompt":"Recall something you believed and later discovered was false. Why had it seemed convincing?","guidingQuestions":["Which topics do you find hardest to think about fairly?","What is one belief you hold where you could say what would change your mind?","Whose opinions do you accept without checking, and why?"]}'::jsonb, '{"text":"Verification is a Quranic command: when someone unreliable brings news, investigate, so that you do not harm people out of ignorance and then regret it. The Quran also forbids pursuing what you have no knowledge of, because hearing, sight and heart will all be questioned. The Prophet ﷺ warned that it is enough of a lie for a person to pass on everything he hears.","sources":["Quran 49:6","Quran 17:36","Sahih Muslim (Introduction), hadith 5","Sunan Abi Dawud 4992 (sahih)"]}'::jsonb, 2),
('intellectual/creativity-and-innovation', 'intellectual', 'creativity-and-innovation', 'Creativity & Innovation', '💡', 'Creativity is a process you can practise: generate many ideas, then choose and improve the best.', '["Distinguish divergent thinking from convergent thinking.","Use the SCAMPER prompts to generate new ideas from an existing one.","Explain why constraints and early failures help creative work."]'::jsonb, 12, 20, '{"title":"Many Ideas First, Good Ideas Second","explanation":"Creativity is producing something both new and useful. It is not limited to art, and it is not a gift that only some people have. It is a process with two phases, described by psychologist J. P. Guilford. Divergent thinking generates many possible ideas without judging them. Convergent thinking then evaluates, selects and refines. Most people fail at creativity because they do both at once, criticising each idea the moment it appears.\n\nSo separate the phases. In the first, aim for quantity: write twenty ideas, including silly ones. Your first few will be obvious, and the interesting ones tend to come later. In the second phase, choose and improve.\n\nWhen you are stuck, use SCAMPER, a checklist of prompts applied to something that already exists: Substitute, Combine, Adapt, Modify, Put to another use, Eliminate, Reverse. Most innovations are recombinations of existing things, so these prompts work surprisingly well.\n\nInnovation is creativity carried through to use. It needs testing: build a rough version quickly, show it to real people, learn and adjust. Early versions are supposed to be imperfect. Limits on time, money or materials often help, because they force you to stop following the obvious route.","keyPoints":["Creativity means new and useful, and it can be practised.","Generate ideas first (divergent), judge them afterwards (convergent).","SCAMPER: Substitute, Combine, Adapt, Modify, Put to another use, Eliminate, Reverse.","Test rough versions early; constraints and failures improve the result."],"examples":[{"title":"The kuih stall","scenario":"Sales at Aisyah''s family kuih stall are flat. Using SCAMPER she lists ideas: Combine (kuih gift boxes), Adapt (pre-orders through WhatsApp), Put to another use (mini kuih for office meetings).","takeaway":"She tests pre-orders for one week with ten customers. It works, and the office boxes follow. Structured prompts plus a small test turned vague worry into a real improvement."},{"title":"Twenty ideas","scenario":"A class must raise funds. The first three suggestions are a bake sale, a car wash and a jogathon. Their teacher insists on twenty ideas before any discussion. Idea seventeen, a repair café where students fix bicycles and phones, wins.","takeaway":"The original ideas appeared only after the obvious ones were used up. Quantity came before quality."}],"practicalTip":"Take an ordinary object near you and set a three-minute timer. Write as many alternative uses for it as you can without judging any. Try again tomorrow with a different object and compare your count.","deeperInsight":"Ideas often arrive in the shower or on a walk. When you stop concentrating, the brain keeps working in the background and makes looser connections. This only happens after focused effort on the problem, so alternate hard thinking with real breaks away from screens."}'::jsonb, '{"prompt":"Think of a small problem that annoys you every day. What are five different ways it could be solved?","guidingQuestions":["When do your best ideas usually come to you?","Do you tend to dismiss your own ideas too early?","What would you try if you were not worried about looking foolish?"]}'::jsonb, '{"text":"In matters of worldly skill, the Prophet ﷺ welcomed expertise and new methods. When his advice on pollinating date palms did not help the farmers, he told them, ''You know best the affairs of your world.'' At the Battle of the Trench he adopted Salman al-Farisi''s suggestion of digging a trench, a technique new to Arabia. Beneficial innovation in worldly matters is encouraged, while acts of worship stay as they were taught.","sources":["Sahih Muslim 2363","Sirah: the Battle of the Trench (al-Khandaq), 5 AH"]}'::jsonb, 3),
('intellectual/cognitive-skills', 'intellectual', 'cognitive-skills', 'Cognitive Skills', '🧠', 'Evidence-based ways to sharpen focus and memory: single-tasking, retrieval practice and spacing.', '["Explain why multitasking reduces the quality of mental work.","Use retrieval practice and spaced repetition when studying.","Set up a focused work session using timed intervals."]'::jsonb, 12, 20, '{"title":"Attention Is the Gate to Memory","explanation":"Cognitive skills are the mental tools you use to take in, hold and use information: attention, working memory, long-term memory and problem-solving. They can be trained, mainly by how you work, not by brain-game apps.\n\nAttention comes first, because you cannot remember what you never properly noticed. The brain does not truly multitask on demanding work. It switches rapidly between tasks, and every switch costs time and accuracy. Studying with a chat window open means paying that cost again and again. Working memory, the mental space where you hold information while using it, is also small, at about four items at once. Writing things down frees that space for thinking.\n\nTwo study methods have especially strong evidence. Retrieval practice means pulling information out of memory instead of putting it in again: close the book and write what you remember, or answer practice questions. Spaced repetition means reviewing material at increasing intervals, such as after one day, three days, a week and two weeks, instead of cramming it into one night.\n\nTo protect attention, work in timed blocks. The Pomodoro technique uses 25 minutes of single-task focus followed by a 5-minute break. Sleep, exercise and food are the foundation of all of it.","keyPoints":["Demanding multitasking is really task-switching, and each switch has a cost.","Working memory holds only about four items, so write things down.","Retrieval practice (testing yourself) beats re-reading.","Spacing reviews over days beats cramming the same hours into one night."],"examples":[{"title":"Two ways to revise Biology","scenario":"Suresh re-reads his notes three times and feels confident. Amal reads once, closes the book and writes everything she can recall, then checks what she missed. A week later, Amal remembers far more.","takeaway":"Re-reading creates familiarity, which feels like knowledge. Recalling from memory is harder and that effort is what strengthens the memory."},{"title":"The phone on the desk","scenario":"Ling studies for two hours with her phone face-up beside her. She checks it every few minutes and finishes one page of exercises. The next day she leaves it in another room and finishes three pages in an hour.","takeaway":"Each glance broke her concentration and needed minutes to rebuild. Removing the distraction worked better than trying to resist it."}],"practicalTip":"For your next study session: phone in another room, one subject only, timer set to 25 minutes. When it rings, close the book and write down everything you remember for two minutes. Then take a five-minute break.","deeperInsight":"Effective learning often feels worse than ineffective learning. Self-testing and spacing feel slow and effortful, while re-reading and cramming feel smooth. Researchers call this productive struggle ''desirable difficulty''. If studying feels too easy, it is probably not working."}'::jsonb, '{"prompt":"Describe your last study session honestly. How many minutes of it were truly focused?","guidingQuestions":["What interrupts your attention most often?","Do you usually re-read, or test yourself?","What one change to your study space would protect your focus?"]}'::jsonb, '{"text":"The Quran praises ''people of understanding'' who reflect deeply on the creation of the heavens and the earth, and it repeatedly asks, ''Will you not use reason?'' The Prophet ﷺ said that two blessings are wasted by many people: health and free time. Guarding your attention and using your mind well is a way of being grateful for the intellect Allah gave you.","sources":["Quran 3:190-191","Sahih al-Bukhari 6412"]}'::jsonb, 4),
('intellectual/cultural-awareness', 'intellectual', 'cultural-awareness', 'Cultural Awareness', '🌍', 'Understanding your own cultural lens and engaging respectfully with people whose lens is different.', '["Explain how culture shapes behaviour in ways people rarely notice.","Tell the difference between a generalisation and a stereotype.","Respond with curiosity when you meet an unfamiliar custom."]'::jsonb, 12, 20, '{"title":"Everyone Has an Accent","explanation":"Culture is the shared set of values, habits and unwritten rules a group lives by: how to greet, what counts as polite, how directly to speak, what to eat and when. You absorb your own culture so early that it feels like ''normal'', and other ways can seem strange. Cultural awareness begins with noticing that your normal is one of many.\n\nMalaysia is a daily classroom for this. Malays, Chinese, Indians, the Orang Asli, and the many peoples of Sabah and Sarawak such as the Kadazan-Dusun and Iban live side by side, with different languages, faiths and festivals. Small things carry meaning: removing shoes before entering a home, using the right hand to give and receive, how elders are addressed, what food a guest can eat.\n\nOne helpful idea comes from anthropologist Edward Hall. In high-context cultures, much of the message is carried by tone, relationship and what is left unsaid. In low-context cultures, people are expected to say exactly what they mean. Neither is better, but misunderstandings arise when the two meet.\n\nBeware of stereotypes, which are fixed beliefs applied to every member of a group. A generalisation (''many families here value...'') stays open to exceptions. A stereotype does not. The best tool is respectful curiosity: observe first, ask politely, and assume good intent.","keyPoints":["Your own culture feels like ''normal'', which makes it hard to see.","Communication styles differ: some cultures rely on context, others on explicit words.","Generalisations stay open to exceptions; stereotypes do not.","Observe, ask respectfully and assume good intent when customs differ."],"examples":[{"title":"The open house","scenario":"Jason is invited to his friend Hafiz''s Hari Raya open house for the first time. Unsure what to do, he asks beforehand, ''Is there anything I should know so I don''t do something rude?'' Hafiz explains about shoes, greetings and eating with the right hand.","takeaway":"Asking in advance showed respect and removed the anxiety. Most people are glad to explain their customs to someone who is sincerely interested."},{"title":"\"She never says what she thinks\"","scenario":"In a group project, Emma, an exchange student, finds her teammate Mei ''unclear'' because Mei says ''maybe that could be difficult'' instead of ''no''. Mei finds Emma blunt.","takeaway":"They are using different communication styles, not showing bad character. Once they talk about it, Emma learns to hear a soft ''no'', and Mei learns that directness from Emma is not rudeness."}],"practicalTip":"This week, learn three things about a culture or faith different from your own, from a person and not only from the internet: a greeting, a festival and a food. Ask them what outsiders most often misunderstand.","deeperInsight":"Learning another language does more than add vocabulary. Languages divide up the world differently, with words for relationships, feelings and courtesies that have no exact match elsewhere. Even a few phrases in someone''s mother tongue show respect and let you glimpse how they see things."}'::jsonb, '{"prompt":"What is one custom from your own family or culture that an outsider might find surprising?","guidingQuestions":["When did you last feel like the outsider, and what helped?","Is there a group you hold a stereotype about? Where did it come from?","Who could you learn from this month about a way of life different from yours?"]}'::jsonb, '{"text":"The Quran presents human diversity as intended and as a sign of Allah: the variety of your languages and colours is among His signs, and people were made into nations and tribes in order to know one another. Honour comes from taqwa alone. In his Farewell Sermon the Prophet ﷺ declared that no Arab is superior to a non-Arab, nor white to black, except by piety.","sources":["Quran 30:22","Quran 49:13","Musnad Ahmad 23489 (sahih)"]}'::jsonb, 5),
('emotional/emotional-intelligence', 'emotional', 'emotional-intelligence', 'Emotional Intelligence', '😊', 'Recognising emotions in yourself and others, and choosing your response instead of reacting.', '["Name the four areas of emotional intelligence.","Label your emotions precisely instead of using broad words.","Use a pause between a feeling and your response to it."]'::jsonb, 12, 20, '{"title":"Name It to Manage It","explanation":"Emotional intelligence (EI) is the ability to recognise, understand and manage emotions, both your own and other people''s. Psychologist Daniel Goleman''s well-known model has four areas. Self-awareness is knowing what you feel and why. Self-management is handling those feelings so that they do not control your behaviour. Social awareness, including empathy, is reading what others feel. Relationship management is using all of this to communicate, cooperate and resolve conflict.\n\nEverything starts with self-awareness, and self-awareness starts with vocabulary. ''I feel bad'' could mean disappointed, embarrassed, jealous, lonely or exhausted, and each needs a different response. Brain-imaging research led by Matthew Lieberman found that putting a feeling into words reduces activity in the brain''s alarm centre. Simply naming an emotion begins to calm it.\n\nEmotions themselves are not good or bad. They are information: anger often signals that a boundary was crossed, fear that something matters, sadness that something was lost. What you can choose is the response. Between feeling and action there is a gap, and EI is the skill of widening it. Notice the feeling, name it, breathe, then decide what to do. Empathy uses the same skill outward: asking what another person might be feeling before you judge what they did.","keyPoints":["EI has four areas: self-awareness, self-management, social awareness, relationship management.","Precise emotional vocabulary leads to better responses.","Naming a feeling reduces its intensity.","Emotions are information; behaviour is a choice."],"examples":[{"title":"\"I''m just angry\"","scenario":"Imran snaps at his mother after school and says he is ''just angry''. Later, writing in a journal, he realises the feeling was embarrassment: a teacher criticised his work in front of the class.","takeaway":"Once he names the real emotion, the right action becomes clear. He apologises to his mother and decides to ask the teacher for feedback privately."},{"title":"The quiet teammate","scenario":"Chloe is annoyed that her lab partner has stopped contributing. Before complaining, she asks, ''You''ve seemed quiet this week. Is everything okay?'' He explains that his grandmother is in hospital.","takeaway":"Asking before judging is empathy in practice. The problem was not laziness, and they agree to split the work differently for now."}],"practicalTip":"Three times a day for one week, pause and complete this sentence in a note on your phone: ''Right now I feel ___ because ___.'' Use a word more specific than good, bad, fine or stressed.","deeperInsight":"Emotional intelligence is not the same as being calm or ''nice'' all the time, and it is not hiding what you feel. Suppressing emotions tends to make them return more strongly. The skill is to feel fully and still act wisely."}'::jsonb, '{"prompt":"What was the strongest emotion you felt today, and what was it telling you?","guidingQuestions":["Which emotion do you find hardest to admit to, even to yourself?","When did you last react in a way you later regretted? What were you feeling just before?","Who around you might be struggling in a way you have not asked about?"]}'::jsonb, '{"text":"The Prophet ﷺ showed that deep feeling and firm faith go together. When his young son Ibrahim died, he wept and said: the eyes shed tears and the heart grieves, and we say only what pleases our Lord. He felt fully, named the feeling honestly and still governed his words. He was also attentive to what others felt, shortening the prayer when he heard a child crying out of mercy for its mother.","sources":["Sahih al-Bukhari 1303","Sahih al-Bukhari 709"]}'::jsonb, 1),
('emotional/stress-management', 'emotional', 'stress-management', 'Stress Management', '🧘', 'What stress does in your body, when it helps, when it harms, and practical ways to bring it down.', '["Describe the body''s stress response and its purpose.","Distinguish helpful short-term stress from harmful chronic stress.","Use a breathing technique and a planning technique to reduce stress."]'::jsonb, 12, 20, '{"title":"Stress Is a Signal, Not an Enemy","explanation":"Stress is your body''s response to a demand. When your brain detects a challenge, it releases adrenaline and cortisol. Your heart beats faster, your breathing quickens and your muscles tense. This fight-or-flight response evolved to help you deal with danger, and in short bursts it is useful: a moderate level of stress before an exam or a match sharpens focus and energy.\n\nThe trouble starts when stress is too intense or never switches off. Chronic stress, lasting weeks or months, is linked with poor sleep, headaches, stomach problems, irritability, low mood and difficulty concentrating. Learn your own early warning signs, because they appear long before a crisis.\n\nManaging stress works on two levels. The first is calming the body. Slow breathing with a long exhale activates the body''s rest-and-recover system. Try box breathing: in for four counts, hold for four, out for four, hold for four, and repeat for a few minutes. Movement, sleep and time outdoors all reduce stress hormones too. The second level is dealing with the cause. Write down everything on your mind, then sort the list into what you can control and what you cannot. For the first group, choose the next small action. For the second, practise letting go. Talking to someone you trust helps on both levels.","keyPoints":["The stress response prepares the body for action and is helpful in short bursts.","Chronic stress that never switches off harms sleep, mood and health.","Slow breathing with a long exhale calms the body within minutes.","Sort worries into what you can control and what you cannot, then act on the first group."],"examples":[{"title":"Exam week overload","scenario":"With five papers in six days, Farid feels paralysed and keeps scrolling instead of studying. He writes every task on paper, crosses out what he cannot change (the timetable), and breaks the rest into one-hour blocks.","takeaway":"Getting the worries out of his head and onto paper made them finite. A clear next step replaced the frozen feeling."},{"title":"Before the presentation","scenario":"Mei''s hands shake before a class presentation. She does two minutes of box breathing in the corridor and tells herself, ''This energy is my body getting ready.''","takeaway":"Slow breathing settled her body, and seeing the nervous energy as preparation instead of a threat helped her use it."}],"practicalTip":"Practise box breathing for two minutes each night this week, when you are calm. A technique you have rehearsed is far easier to use when you are actually stressed.","deeperInsight":"How you interpret stress changes its effect. People who see their racing heart as the body preparing to perform tend to do better under pressure than those who read it as a sign of failing. You cannot always lower the demand, but you can change what you tell yourself about your response."}'::jsonb, '{"prompt":"How does your body tell you that you are stressed? Where do you feel it first?","guidingQuestions":["What are your three biggest sources of stress right now?","Which of them are within your control?","What do you usually do when stressed, and does it actually help?"]}'::jsonb, '{"text":"The Quran gives two anchors for a stressed heart: ''Surely in the remembrance of Allah do hearts find rest'', and ''Allah does not burden a soul beyond what it can bear.'' The Prophet ﷺ regularly sought refuge in Allah from anxiety and grief, which shows that feeling worried is human, and that turning to Allah with it, alongside practical steps, is the believer''s way.","sources":["Quran 13:28","Quran 2:286","Sahih al-Bukhari 6369"]}'::jsonb, 2),
('emotional/coping-mechanisms', 'emotional', 'coping-mechanisms', 'Coping Mechanisms', '❤️', 'Telling healthy coping from unhealthy coping, and building your own toolkit for hard days.', '["Distinguish problem-focused coping from emotion-focused coping.","Recognise coping habits that give short relief but cause long-term harm.","Build a personal coping toolkit and know when to seek help."]'::jsonb, 12, 20, '{"title":"Relief Now, or Better Later?","explanation":"A coping mechanism is anything you do to deal with difficult feelings or situations. Everyone has them. What matters is whether they help you over time.\n\nPsychologists Richard Lazarus and Susan Folkman described two broad types. Problem-focused coping tackles the cause: making a plan, asking for help, having the difficult conversation. Emotion-focused coping soothes the feeling: talking to a friend, exercising, praying, writing, resting. You need both. When a situation can be changed, work on the problem. When it cannot, as with a loss or a result that is already final, care for the feeling.\n\nUnhealthy coping gives quick relief and a later cost. Common examples are avoiding the problem, endless scrolling or gaming to numb out, overeating or not eating, lashing out at others, smoking or vaping, and self-harm. A simple test is to ask: ''Will I feel better or worse about this tomorrow?''\n\nBuild a toolkit before you need it. Include something for your body (a walk, a shower, sleep), something for your mind (journaling, reframing the thought), something for connection (a person you can message), and something for meaning (prayer, nature, helping someone). If your feelings are overwhelming, last more than two weeks, or include thoughts of harming yourself, talk to a trusted adult or call a helpline such as Befrienders KL (03-7627 2929) or Talian Kasih (15999).","keyPoints":["Problem-focused coping changes the situation; emotion-focused coping soothes the feeling.","Use problem-focused coping for what you can change and emotion-focused coping for what you cannot.","Unhealthy coping feels good now and worse later.","Asking for help is a healthy coping skill, not a weakness."],"examples":[{"title":"After a bad result","scenario":"Syafiq fails a trial exam. His first instinct is to game all weekend and avoid thinking about it. Instead he lets himself be upset on Friday night, talks to his cousin, and on Saturday asks his teacher which topics to focus on.","takeaway":"He used emotion-focused coping first (feel it, talk about it) and then problem-focused coping (make a plan). Avoidance would only have delayed the pain."},{"title":"What cannot be fixed","scenario":"Anjali''s close friend moves overseas. There is no problem to solve, and she feels low for weeks. She starts a weekly video call, joins a badminton group and writes about what she misses.","takeaway":"When the situation cannot change, healthy coping means caring for the feeling and building new sources of connection."}],"practicalTip":"Write your toolkit on a card or phone note: two things for your body, two for your mind, two people you can contact and one helpline number. Decide on it now, while you are calm.","deeperInsight":"Avoidance is the most common unhealthy coping habit because it works at first: the bad feeling drops as soon as you look away. The brain learns to avoid again, and the problem grows in the dark. Facing a hard thing in small steps teaches the opposite lesson, that you can handle it."}'::jsonb, '{"prompt":"What do you usually do when you have had a very bad day?","guidingQuestions":["Does that habit leave you feeling better or worse the next day?","Which part of your toolkit is weakest: body, mind, connection or meaning?","Who is one person you could tell if things became too heavy?"]}'::jsonb, '{"text":"Allah directs believers to two resources in difficulty: ''Seek help through patience and prayer.'' He also gives a promise repeated twice in one surah: with hardship comes ease. The Prophet ﷺ taught that no fatigue, illness, worry, grief or harm afflicts a Muslim, even the prick of a thorn, without Allah expiating some of his sins by it. Hardship met with sabr is never wasted.","sources":["Quran 2:153","Quran 94:5-6","Sahih al-Bukhari 5641","Sahih Muslim 2573"]}'::jsonb, 3),
('emotional/building-resilience', 'emotional', 'building-resilience', 'Building Resilience', '🧠', 'Resilience is a set of learnable habits that help you recover from setbacks and grow through them.', '["Define resilience and explain why it is not the same as never struggling.","Identify the main factors that make people more resilient.","Reframe a setback using a more accurate and helpful explanation."]'::jsonb, 12, 20, '{"title":"Bending Without Breaking","explanation":"Resilience is the ability to adapt and recover when life is hard. Resilient people still feel pain, fear and disappointment. What differs is that they find a way back, and often come out with new strength or understanding. Researcher Ann Masten calls resilience ''ordinary magic'', because it grows from ordinary things and not from rare personal toughness.\n\nSeveral factors show up again and again in resilience research. The strongest is supportive relationships: at least one person who believes in you. Others are a sense of purpose, belief that your actions make a difference, practical problem-solving skills, the ability to manage strong feelings, and looking after your body.\n\nHow you explain a setback to yourself also matters. Psychologist Martin Seligman found that people struggle most when they see a bad event as personal (''it''s all my fault''), pervasive (''it ruins everything'') and permanent (''it will always be like this''). A resilient explanation is more accurate: what part was mine and what was not, which area of life is affected and which is fine, and what can change with time and effort.\n\nResilience grows like a muscle. Each difficulty you face and get through, with support, becomes evidence for the next one: ''I have handled hard things before.''","keyPoints":["Resilience means recovering and adapting, not avoiding all struggle.","Supportive relationships are the strongest resilience factor.","Challenge the three Ps: personal, pervasive, permanent.","Past difficulties you have come through are evidence you can use."],"examples":[{"title":"Not selected","scenario":"Hafiz is dropped from the school football team and thinks, ''I''m useless at everything and I always will be.'' His coach asks him to write what is actually true. Hafiz writes: ''My fitness was below the others this term. My schoolwork and friendships are fine. I can train and try again in three months.''","takeaway":"The second version is not fake positivity. It is more accurate, it limits the damage to one area, and it points to an action."},{"title":"The business that failed","scenario":"Li Na''s online craft shop makes no sales in two months and she closes it. She lists what she learned about pricing, photos and customers, and asks a cousin who runs a shop for advice before starting again.","takeaway":"Treating the failure as information, and reaching out to someone supportive, turned an ending into preparation for the next attempt."}],"practicalTip":"Write a ''proof list'' of three hard things you have already come through, and what helped each time. Keep it where you can read it the next time something goes wrong.","deeperInsight":"Resilience is not something you build alone. Children and teenagers who do well after serious hardship almost always had at least one stable, caring adult. Asking for support is the main way resilience is built, and being that person for someone else builds it too."}'::jsonb, '{"prompt":"Think of the hardest thing you have come through so far. What, or who, helped you get through it?","guidingQuestions":["When something goes wrong, which of the three Ps do you fall into most?","Who is on your support team, and do they know it?","What did that hard experience teach you that you still use?"]}'::jsonb, '{"text":"The Prophet ﷺ described the believer''s situation as remarkable: all of it is good for him. If something pleasing happens he is grateful, and that is good for him. If hardship strikes he is patient, and that is good for him. The Quran also tells of prophets who endured loss and waiting, such as Ya''qub عليه السلام, who answered grief with ''beautiful patience'' and never lost hope in Allah''s mercy.","sources":["Sahih Muslim 2999","Quran 12:18","Quran 12:87"]}'::jsonb, 4),
('emotional/positive-psychology', 'emotional', 'positive-psychology', 'Positive Psychology', '✨', 'The science of what makes life go well, and small practices shown to raise well-being.', '["Explain what positive psychology studies and what it does not claim.","List the five elements of the PERMA model of well-being.","Carry out the ''three good things'' exercise."]'::jsonb, 12, 20, '{"title":"More Than the Absence of Problems","explanation":"For most of its history, psychology focused on what goes wrong. Positive psychology, a field launched by Martin Seligman in the late 1990s, studies what goes right: the conditions under which people and communities do well. It does not say you should be happy all the time or ignore problems. Its claim is that well-being can be understood and deliberately built.\n\nSeligman''s PERMA model describes five building blocks. Positive emotion includes joy, gratitude, calm and hope. Engagement is being fully absorbed in an activity that stretches your skills, a state Mihaly Csikszentmihalyi called flow. Relationships are close, supportive connections, which are the strongest single predictor of well-being. Meaning is belonging to and serving something larger than yourself. Accomplishment is working towards goals and achieving them.\n\nThe field has tested practical exercises. In ''three good things'', you write down three things that went well each night and why they happened. In a study by Seligman and colleagues, people who did this for a week reported feeling happier for months afterwards. Other tested practices include using your personal strengths in new ways, performing deliberate acts of kindness, and expressing thanks directly to someone. The brain naturally notices threats more than good things, and these practices train attention in the other direction.","keyPoints":["Positive psychology studies what helps people do well; it does not deny difficulty.","PERMA: Positive emotion, Engagement, Relationships, Meaning, Accomplishment.","Close relationships are the strongest predictor of well-being.","Simple exercises such as ''three good things'' have measurable effects."],"examples":[{"title":"Three good things","scenario":"Hui Min feels her days are ''all the same and all tiring''. For one week she writes three good things each night: a friend shared notes, the rain cooled the evening, she finally understood a chemistry topic.","takeaway":"Her days did not change, but what she noticed did. By the end of the week she finds herself looking for good moments during the day."},{"title":"Finding flow","scenario":"Adam drifts through most homework but loses track of time when coding small games. The challenge is just above his current skill and he gets instant feedback when something works.","takeaway":"Flow happens when challenge and skill are well matched. Knowing where you find it is a clue to your strengths and to work you may love."}],"practicalTip":"Tonight, write down three things that went well today and one sentence on why each happened. Repeat for seven nights and notice whether your attention during the day begins to shift.","deeperInsight":"Chasing happiness directly often backfires, and buying things brings only brief satisfaction because people adapt quickly to what they have. Well-being tends to arrive as a side effect of good relationships, meaningful effort and helping others."}'::jsonb, '{"prompt":"Which of the five PERMA elements is strongest in your life right now, and which is weakest?","guidingQuestions":["When did you last lose track of time doing something you enjoy?","Who makes your life better simply by being in it? Have you told them?","What gives your daily effort a sense of meaning?"]}'::jsonb, '{"text":"Gratitude is the Quran''s formula for increase: ''If you are grateful, I will surely give you more.'' The Prophet ﷺ gave a practical rule for contentment: look at those who have less than you, not at those who have more, so that you do not belittle Allah''s favours upon you. Lasting well-being, in the Islamic view, rests on a heart that is content and at rest with its Lord.","sources":["Quran 14:7","Sahih Muslim 2963","Quran 89:27-30"]}'::jsonb, 5),
('environmental/sustainable-living', 'environmental', 'sustainable-living', 'Sustainable Living', '♻️', 'Everyday choices about what you buy, use and throw away, and which ones make the biggest difference.', '["Explain what sustainability means in everyday terms.","Rank the waste hierarchy from most to least effective action.","Identify the changes in your own routine that would cut the most waste."]'::jsonb, 12, 20, '{"title":"Use Less Before You Recycle More","explanation":"Sustainable living means meeting your needs today without making it harder for others, including future generations, to meet theirs. In practice it is about three flows through your life: the things you buy, the energy and water you use, and the waste you create.\n\nThe waste hierarchy puts actions in order of impact. Refuse what you do not need. Reduce what you do use. Reuse items many times. Repurpose or repair them when they wear out. Recycle only what is left. Recycling comes last because it still takes energy and transport, and many items placed in recycling bins are never actually recycled. The most sustainable product is usually the one you did not buy.\n\nFocus on what matters most. Food waste is a major one: Malaysian households throw away thousands of tonnes of food every day, and a large share of it was still edible. Single-use plastics such as bags, straws, cups and food containers are another. Clothing is a third, since fast fashion uses large amounts of water and is often worn only a few times. At home, air conditioning and water heating are typically the biggest users of electricity.\n\nYou do not have to be perfect. A few consistent habits, such as carrying a bottle and a bag, taking only the food you will finish, and switching off what you are not using, add up across a year and influence the people around you.","keyPoints":["Sustainability means meeting present needs without harming the future''s ability to do the same.","The waste hierarchy: refuse, reduce, reuse, repurpose, recycle, in that order.","Food waste, single-use plastic and fast fashion are high-impact areas for young people.","Consistent small habits beat occasional grand gestures."],"examples":[{"title":"The canteen audit","scenario":"For one week, Aina counts what she throws away at school: five plastic cups, five straws, three polystyrene boxes and about a third of each lunch.","takeaway":"She brings a bottle and a container and asks for smaller rice portions. Her weekly waste falls to almost nothing, and she saves money on drinks."},{"title":"The RM15 T-shirt","scenario":"Ethan buys five cheap T-shirts in a sale. Two shrink, one fades and two are never worn. His sister buys one good shirt second-hand and wears it for three years.","takeaway":"Cost per wear, not price, shows the real value. Buying less and choosing well is cheaper and creates far less waste."}],"practicalTip":"Build a ''leave-the-house kit'': a refillable bottle, a foldable bag and a food container. Keep it by the door or in your school bag for one week and count how many single-use items you avoid.","deeperInsight":"Individual habits matter partly because they are visible. When one person in a class brings a bottle, others follow, canteens adapt and norms shift. Your influence on what the people around you see as normal is often larger than your personal footprint."}'::jsonb, '{"prompt":"Look at what you threw away yesterday. What was the largest item or category?","guidingQuestions":["Which single-use item do you use most often?","What did you buy in the last month that you did not really need?","Which one habit could you change this week with almost no effort?"]}'::jsonb, '{"text":"The Quran forbids waste in plain terms: eat of its fruit and give its due on the day of harvest, and do not be excessive, for Allah does not love the wasteful. It describes those who squander as brothers of the devils. The Prophet ﷺ taught people to pick up a dropped morsel, clean it and eat it, and to finish what is in the dish, because you do not know in which part of your food the blessing lies. Moderation in consumption is obedience, not just good ecology.","sources":["Quran 6:141","Quran 17:26-27","Sahih Muslim 2033"]}'::jsonb, 1),
('environmental/conservation-efforts', 'environmental', 'conservation-efforts', 'Conservation Efforts', '🌳', 'Why biodiversity matters, what threatens it in Malaysia, and how ordinary people help protect it.', '["Explain what biodiversity is and why people depend on it.","Name the main threats to wildlife and habitats.","Describe practical ways a young person can support conservation."]'::jsonb, 12, 20, '{"title":"We Live Inside the Web","explanation":"Biodiversity is the variety of life in a place: its plants, animals, fungi and microorganisms, and the ecosystems they form. People depend on it constantly. Forests store carbon, release oxygen, hold soil in place and regulate rainfall. Mangroves protect coasts from storms and serve as nurseries for fish. Insects pollinate many of the crops we eat. When species disappear, these services weaken.\n\nMalaysia is recognised as one of the world''s megadiverse countries. Its rainforests are among the oldest on Earth, and its seas hold some of the richest coral reefs. Much of this is under pressure. The Malayan tiger, the national animal, is critically endangered, with fewer than 150 estimated to remain in the wild. The main threats are the same worldwide: habitat loss from clearing land, poaching and illegal wildlife trade, pollution, invasive species and climate change.\n\nConservation is the work of protecting and restoring nature. Governments create protected areas and laws, and scientists monitor species. Ordinary people matter too. You can refuse to buy wildlife products or exotic pets, choose products with credible sustainability certification, reduce waste and plastic, join tree-planting or river and beach clean-ups, record wildlife sightings for citizen-science projects, and speak up when you see illegal dumping or trade. Learning the names of the plants and birds around you is a real first step, because people protect what they know.","keyPoints":["Biodiversity provides clean air and water, food, climate regulation and protection from disasters.","Malaysia is megadiverse, and species such as the Malayan tiger are critically endangered.","Major threats: habitat loss, poaching, pollution, invasive species, climate change.","Individuals help through their purchases, volunteering, reporting and awareness."],"examples":[{"title":"The river clean-up","scenario":"A school group in Selangor spends one morning a month collecting rubbish along a nearby river and records what they find. After six months their data show that food packaging is the largest category, and they present it to the local council.","takeaway":"Clean-ups remove waste, and the records they produce can support better bins, signs or enforcement. Action plus evidence is more powerful than action alone."},{"title":"The ''cute'' pet","scenario":"Marcus sees a slow loris for sale online and thinks it would make an unusual pet. He looks it up and learns it is a protected species taken from the wild, and that its teeth are often cut out by traders.","takeaway":"Demand drives the illegal trade. He reports the listing instead. Checking before buying is one of the simplest conservation acts."}],"practicalTip":"Learn to identify five birds, trees or insects that live within walking distance of your home. Use a field guide or a nature identification app, and write down where and when you saw each one.","deeperInsight":"Ecosystems can absorb damage for a long time and then change suddenly. Removing one species may seem to have no effect until a link in the food web breaks. This is why conservationists aim to protect whole habitats, not just individual famous animals."}'::jsonb, '{"prompt":"Which natural place near you would you be saddest to lose? Why does it matter to you?","guidingQuestions":["How many local plants or animals can you actually name?","Which of your regular purchases might be linked to habitat loss?","What conservation activity near you could you join once this term?"]}'::jsonb, '{"text":"Humanity is placed on earth as khalifah, a steward answerable for what was entrusted. The Quran warns that corruption has appeared on land and sea because of what people''s hands have earned. The Prophet ﷺ said that the world is sweet and green, and that Allah has made you successors in it to see how you will act. He also told of a person forgiven for giving water to a thirsty dog: there is reward in kindness to every living creature.","sources":["Quran 2:30","Quran 30:41","Sahih Muslim 2742","Sahih al-Bukhari 2363"]}'::jsonb, 2),
('environmental/appreciation-of-nature', 'environmental', 'appreciation-of-nature', 'Appreciation of Nature', '🏞️', 'How time in nature restores attention and mood, and ways to build it into an ordinary week.', '["Describe how time in nature affects stress, mood and attention.","State how much weekly time outdoors research links with better well-being.","Practise noticing nature using your senses."]'::jsonb, 10, 20, '{"title":"Two Hours a Week Outside","explanation":"People evolved outdoors, and the body still responds to natural settings. Research links time in green and blue spaces, such as parks, forests, rivers and beaches, with lower stress, better mood and improved concentration. A large study in England, published in 2019, found that people who spent at least 120 minutes a week in nature were noticeably more likely to report good health and well-being than those who spent none. It did not matter whether the time came in one long visit or several short ones.\n\nOne explanation is attention restoration theory, proposed by Rachel and Stephen Kaplan. Screens, traffic and study demand directed attention, which tires with use. Natural scenes hold your attention gently, through moving leaves, water and birdsong, which lets the tired system recover. This is why a walk outside often clears your head better than a break spent scrolling.\n\nAppreciation is more than being outdoors. It means noticing. In Japan, the practice of shinrin-yoku, or ''forest bathing'', means walking slowly among trees with all the senses open. You can do the same anywhere: look for five shades of green, listen for the furthest sound, feel the air on your skin. Nature is also closer than it seems. A neighbourhood park, a tree outside the window, the evening sky or a pot plant on a balcony all count.","keyPoints":["Time in natural settings is linked with lower stress and better mood and focus.","About 120 minutes a week, in any combination of visits, is associated with better well-being.","Nature rests the directed attention that screens and study exhaust.","Appreciation means noticing with your senses, and nearby nature counts."],"examples":[{"title":"The study break that worked","scenario":"Dinesh usually takes study breaks on his phone and returns feeling just as foggy. One afternoon he walks around the neighbourhood park for fifteen minutes without earphones.","takeaway":"He comes back clearer and finishes his exercises faster. A scrolling break kept his attention working, while the walk let it rest."},{"title":"The balcony garden","scenario":"Living in a high-rise flat, Sarah feels she has ''no nature''. She plants pandan, chilli and mint in pots on the balcony and spends ten minutes each morning watering them.","takeaway":"Tending something living, even on a small scale, gave her a daily moment of calm and a reason to step outside before school."}],"practicalTip":"Schedule your 120 minutes like any other appointment. For example: three 20-minute walks on weekdays and one hour at a park, hill or beach on the weekend. Leave your earphones in your pocket for at least part of it.","deeperInsight":"Children today spend far less time outdoors than their grandparents did, and many adults can name more brand logos than local trees. Familiarity builds care, so helping a younger sibling or cousin enjoy the outdoors is one of the most lasting contributions you can make to conservation."}'::jsonb, '{"prompt":"Where is your favourite outdoor place, and when were you last there?","guidingQuestions":["Roughly how many minutes did you spend outdoors in nature last week?","What do you notice in your body and mood after time outside?","What piece of nearby nature have you walked past without really seeing?"]}'::jsonb, '{"text":"The Quran repeatedly invites people to look at creation as a way of knowing the Creator: in the creation of the heavens and the earth and the alternation of night and day are signs for people of understanding. It asks, ''Do they not look at the camels, how they are created? And at the sky, how it is raised?'' Reflecting on nature (tafakkur) is an act of worship that strengthens faith and gratitude.","sources":["Quran 3:190-191","Quran 88:17-20","Quran 16:10-11"]}'::jsonb, 3),
('environmental/healthy-personal-space', 'environmental', 'healthy-personal-space', 'Healthy Personal Space', '🏠', 'How your room affects your sleep, focus and mood, and simple ways to make it work for you.', '["Explain how clutter, light, air and noise affect focus and mood.","Set up separate zones for sleep and study, even in a shared room.","Use a short daily reset routine to keep a space in order."]'::jsonb, 10, 20, '{"title":"Your Room Is Part of Your Mind","explanation":"You spend a large part of your life in a few small spaces: your bedroom, your desk, your corner of a shared room. These surroundings influence how you feel and function more than most people realise.\n\nFour things matter most. The first is order. Visual clutter competes for your attention and makes it harder to focus, and a messy space is a constant reminder of unfinished tasks. The second is light. Daylight during the day supports alertness and a healthy body clock, while dim, warm light in the evening prepares you for sleep. The third is air. Stale, humid rooms encourage mould and dust mites, which can trigger allergies and asthma, so open windows daily and keep bedding clean. The fourth is noise and temperature: a cool, quiet, dark room gives the best sleep.\n\nYour brain also links places with activities. If you study, scroll and eat on your bed, the bed stops signalling sleep. Create zones, even tiny ones: a spot for sleep, a spot for study. If you share a room, a particular chair or one side of a table can be your study zone.\n\nKeeping a space healthy is easier with small routines than with big clean-ups. Give every item a ''home'', and do a five-minute reset each evening: clothes away, desk cleared, rubbish out, bag packed for tomorrow.","keyPoints":["Clutter competes for attention and adds background stress.","Daylight by day and dim light at night support your body clock.","Fresh air and clean bedding reduce allergens such as mould and dust mites.","Separate sleep and study zones, and use a five-minute daily reset."],"examples":[{"title":"The desk that disappeared","scenario":"Khairul''s desk is buried under books, cables and snack wrappers, so he studies on his bed and keeps falling asleep. He spends twenty minutes clearing the desk and gives each item a place on a shelf.","takeaway":"With a clear desk he studies sitting up, and his bed goes back to being only for sleep. Both his focus and his sleep improve."},{"title":"Sharing with two brothers","scenario":"Vikram shares a small room with two brothers and has no desk. He agrees with them on a ''quiet hour'' after dinner and claims one end of the dining table, with a box that holds all his study materials.","takeaway":"A healthy space does not need a private room. A consistent spot, a portable kit and an agreement with the family create a study zone anywhere."}],"practicalTip":"Tonight, set a five-minute timer and do a reset: clothes in the basket or cupboard, desk surface cleared, rubbish out, tomorrow''s bag packed. Repeat nightly for a week and notice how your mornings change.","deeperInsight":"Your digital space is part of your personal space. A phone home screen full of notifications and a desktop of scattered files create the same background noise as a messy room. Turning off non-essential notifications is the digital version of clearing your desk."}'::jsonb, '{"prompt":"Look around the space where you sleep or study. What is the first thing you would change?","guidingQuestions":["Where do you study best, and what is different about that place?","Which items in your space have no fixed ''home''?","How does your room make you feel when you walk into it?"]}'::jsonb, '{"text":"Cleanliness holds a high place in Islam: the Prophet ﷺ said that purity is half of faith. He also said that Allah is beautiful and loves beauty, when a man asked whether liking good clothes and shoes was arrogance. Keeping your body, clothes and living space clean and orderly is part of worship, and it prepares a fitting place for prayer.","sources":["Sahih Muslim 223","Sahih Muslim 91","Quran 2:222"]}'::jsonb, 4),
('environmental/community-green-initiatives', 'environmental', 'community-green-initiatives', 'Community Green Initiatives', '🤝', 'Turning environmental concern into a shared project, from first idea to first event.', '["Give examples of green projects suited to a school or neighbourhood.","Plan a small initiative with a clear goal, team and first step.","Explain why collective action achieves more than individual action alone."]'::jsonb, 12, 20, '{"title":"Start Small, Start Together","explanation":"Individual habits matter, but some problems can only be solved together. One person cannot clean a river, set up a recycling point or shade a playground alone. A community green initiative is any organised, shared effort to improve the local environment.\n\nMany such projects are within reach of students. A community garden (kebun komuniti) turns unused land into vegetables and herbs. A recycling collection point at a school or surau makes sorting easy. In Malaysia''s colour system, blue bins take paper, brown take glass, and orange take plastic, aluminium and other metals. Other options include composting food scraps, tree planting, river or beach clean-ups, repair sessions for bicycles and electronics, and swap events for books, uniforms and clothes.\n\nGood projects follow a simple path. Begin with a specific, visible problem (''the field behind the flats is covered in litter''). Find two or three people who care. Ask permission from whoever is responsible, such as the school, the residents'' committee or the local council. Set one small, measurable goal and a date. Give everyone a clear role. Afterwards, share photos and results, thank everyone and decide the next step.\n\nThe first event will be small. That is fine. Visible action attracts people, and a project that starts with five volunteers and continues monthly achieves far more than a large event held once.","keyPoints":["Shared problems need shared action.","Options include gardens, recycling points, composting, tree planting, clean-ups, repair and swap events.","Begin with a specific problem, a small team, permission, one measurable goal and a date.","Regular small events build more than one large one."],"examples":[{"title":"From empty plot to garden","scenario":"Nabila and three neighbours ask their residents'' association for permission to use a weedy corner beside the playground. They start with four raised beds of kangkung, chilli and lemongrass. Within a year, twelve families take turns watering.","takeaway":"A specific place, permission and a modest start made the project real. Others joined once they could see it growing."},{"title":"The uniform swap","scenario":"At the end of the school year, a prefect team collects outgrown uniforms and textbooks, sorts them by size and form, and holds a free swap day in the hall.","takeaway":"Dozens of families save money and hundreds of items stay out of the bin. The idea needed no budget, only organisation."}],"practicalTip":"Write a one-page plan for a green project you could start: the problem, two people you would ask to join, whose permission you need, one measurable goal and a date. Then show it to one of those people this week.","deeperInsight":"Projects usually fail from lack of follow-through, not lack of enthusiasm. A garden needs watering in week ten as well as week one. Before starting, decide who will maintain the project and how responsibility will be handed on when the founders move on."}'::jsonb, '{"prompt":"What is one environmental problem you can see from your home or school?","guidingQuestions":["Who else is bothered by it, and have you ever talked about it?","Who would need to give permission for a project there?","What role would suit you best: organiser, promoter, record-keeper or hands-on worker?"]}'::jsonb, '{"text":"Planting is rewarded as ongoing charity: the Prophet ﷺ said that no Muslim plants a tree or sows a crop from which a bird, a person or an animal eats, except that it is counted as charity for him. He also described removing something harmful from the road as a branch of faith. Working with others to care for shared land is cooperation in righteousness.","sources":["Sahih al-Bukhari 2320","Sahih Muslim 1553","Sahih Muslim 35","Quran 5:2"]}'::jsonb, 5),
('vocational/career-exploration', 'vocational', 'career-exploration', 'Career Exploration', '🧭', 'Using your interests, strengths and values to explore career options through small real-world tests.', '["Identify your interests, strengths and values as the basis for career choices.","Use the RIASEC model to describe the kind of work that suits you.","Test a career idea through an informational interview or a small trial."]'::jsonb, 12, 20, '{"title":"Explore Before You Decide","explanation":"Choosing a career is not one big decision made at seventeen. It is a series of experiments that gradually show where you fit. Most adults change direction several times, and many of today''s jobs did not exist twenty years ago. The aim at your stage is a good next step, not a perfect final answer.\n\nStart with three questions. What interests me, meaning what do I do without being told? What am I good at, according to results and to other people? What do I value: helping others, income, creativity, stability, independence? Work that matches all three is satisfying. Work that matches none is draining, however prestigious it sounds.\n\nPsychologist John Holland''s RIASEC model is a useful map. It describes six broad types of interest: Realistic (hands-on, building, fixing), Investigative (analysing, researching), Artistic (creating, designing), Social (teaching, helping, caring), Enterprising (leading, selling, persuading) and Conventional (organising, working with data and systems). Most people are a mix of two or three, and each combination points to families of careers. Your Harmony personality results give you a starting point.\n\nThen test your ideas in the real world. Talk to someone who does the job and ask what a normal day is like, what they find hard, and how they got there. Shadow them for a day, volunteer, take a short online course or try a small project. A week of real exposure teaches more than months of guessing.","keyPoints":["Career choice is a series of experiments, and changing direction is normal.","Look for the overlap between your interests, your strengths and your values.","RIASEC: Realistic, Investigative, Artistic, Social, Enterprising, Conventional.","Test ideas cheaply through conversations, shadowing, volunteering and small projects."],"examples":[{"title":"\"I''ll be a doctor\"","scenario":"Aiman has planned to study medicine since primary school because his family expects it. He volunteers at a clinic for two weeks and discovers he dislikes the clinical work but loves solving the scheduling and records problems.","takeaway":"The trial was cheap and revealed real information. He begins exploring health informatics and hospital management, fields he had never heard of."},{"title":"The twenty-minute conversation","scenario":"Pei Shan is curious about graphic design but unsure about income. She messages a designer her aunt knows and asks three questions about daily work, pay progression and what she wishes she had known at eighteen.","takeaway":"One short conversation replaced vague worry with facts and gave her a contact in the field."}],"practicalTip":"Write down three careers that interest you. For each one, find one person who does it, through family, teachers or LinkedIn, and prepare three questions. Send one message this week.","deeperInsight":"''Follow your passion'' is incomplete advice. Research suggests that interest often develops after you become good at something useful, not before. Curiosity is the right starting point, and skill, contribution and autonomy tend to turn it into passion over time."}'::jsonb, '{"prompt":"What activity makes you lose track of time, and what does that tell you about the kind of work you might enjoy?","guidingQuestions":["What do other people regularly ask you for help with?","Which matters most to you in future work: income, meaning, creativity, stability or freedom?","Which career have you assumed is ''not for you'' without ever testing it?"]}'::jsonb, '{"text":"Work is honoured in Islam. After the prayer, believers are told to spread through the land and seek the bounty of Allah. The Prophet ﷺ said that no one has ever eaten better food than what he earns by the work of his own hands, and that the Prophet Dawud عليه السلام ate from the work of his hands. Choosing halal work that uses your abilities to benefit others is a way of thanking Allah for them.","sources":["Quran 62:10","Sahih al-Bukhari 2072"]}'::jsonb, 1),
('vocational/skill-development', 'vocational', 'skill-development', 'Skill Development', '🛠️', 'How skills are actually built, which ones employers look for, and how to show what you can do.', '["Distinguish technical skills from transferable (soft) skills.","Apply the principles of deliberate practice to a skill you want to build.","Collect evidence of your skills in a simple portfolio."]'::jsonb, 12, 20, '{"title":"Practise on Purpose","explanation":"Skills fall into two broad groups. Technical or ''hard'' skills are specific to a field: coding, accounting, welding, video editing, a language. Transferable or ''soft'' skills apply everywhere: communication, teamwork, problem-solving, time management and reliability. Employers consistently report that technical skills get people interviews while soft skills get them hired and promoted. A useful picture is the T-shaped person, with deep ability in one area (the vertical bar) and a working understanding of several others (the horizontal bar).\n\nTime alone does not build skill. Psychologist Anders Ericsson studied top performers and found that what set them apart was deliberate practice. It has four features. You work on a specific weakness, not on what you already do well. The task is just beyond your current ability. You get immediate feedback, from a teacher, a recording or a test. And you repeat and adjust. Playing a favourite song a hundred times is not deliberate practice. Slowly working through the difficult bar you keep getting wrong is.\n\nTo build a skill, break it into parts, find good models to copy, practise the hardest part in short focused sessions, and ask for feedback often. Then make the skill visible. A portfolio of real work, such as projects, designs, code, writing, certificates or photographs of what you built, persuades far better than a claim on a résumé.","keyPoints":["Hard skills are field-specific; soft skills transfer to every job.","Aim to be T-shaped: deep in one area, broad across others.","Deliberate practice: target a weakness, stretch slightly, get feedback, repeat.","Evidence of real work is more convincing than a list of claims."],"examples":[{"title":"Learning to edit video","scenario":"Farhan watches editing tutorials for a month but never opens the software. His cousin, an editor, tells him to make one 30-second clip each week and send it for comments. After eight clips his work is clearly better.","takeaway":"Watching is not practising. Small projects with feedback built skill, and the eight clips became the start of his portfolio."},{"title":"The part-time job","scenario":"Kumar works weekends at a bubble tea shop and thinks it is ''just a job''. A teacher helps him list what he has learned: handling customer complaints, cash accuracy, working fast in a team, training a new staff member.","takeaway":"Everyday work builds transferable skills. Naming them, with a specific example for each, makes them usable in applications and interviews."}],"practicalTip":"Choose one skill you want. Write down its weakest sub-skill, schedule three 20-minute practice sessions this week on that part only, and decide who or what will give you feedback.","deeperInsight":"The popular ''10,000-hour rule'' oversimplifies Ericsson''s research. He did not find a magic number, and hours of mindless repetition do little. The quality of practice, including feedback and working at the edge of your ability, matters far more than the total."}'::jsonb, '{"prompt":"What is one skill you have noticeably improved in the last year? What caused the improvement?","guidingQuestions":["Which skill would open the most doors for you if you built it this year?","When you practise, do you work on what is hard or on what is comfortable?","What real evidence could you show someone today of something you can do?"]}'::jsonb, '{"text":"Excellence is a religious duty in Islam. The Prophet ﷺ said that Allah has prescribed ihsan, doing things in the best way, in everything. Skill is also a trust: the Quran records that the daughter of the righteous man recommended hiring Musa عليه السلام because the best person to employ is the one who is strong and trustworthy, joining competence with character.","sources":["Sahih Muslim 1955","Quran 28:26"]}'::jsonb, 2),
('vocational/work-life-balance', 'vocational', 'work-life-balance', 'Work-Life Balance', '⚖️', 'Managing time and energy across study, work, family, rest and faith without burning out.', '["Recognise the warning signs of burnout.","Prioritise tasks using the Eisenhower matrix.","Set boundaries that protect rest, relationships and health."]'::jsonb, 12, 20, '{"title":"You Are Not a Machine","explanation":"Balance does not mean giving equal time to everything. It means that over a week or a month, the important areas of your life, such as study or work, family, health, friends, rest and faith, each get enough of your attention that none of them collapses.\n\nIgnoring balance has a cost. The World Health Organization describes burnout as resulting from chronic stress that has not been successfully managed, with three signs: exhaustion, growing negativity or distance from your work, and reduced effectiveness. Students experience the same pattern. Rest is not a reward for finishing; it is what makes good work possible.\n\nTime management helps you choose. The Eisenhower matrix sorts tasks by two questions: is it urgent, and is it important? Urgent and important tasks, such as tomorrow''s exam, are done now. Important but not urgent ones, such as exercise, revision ahead of time and relationships, are scheduled, and this is where a balanced life is built. Urgent but unimportant ones, such as most notifications, are minimised or delegated. Tasks that are neither are dropped.\n\nBalance also needs boundaries. Decide on a time when schoolwork stops, protect your sleep, keep one activity a week purely for enjoyment, and learn to say, ''I can''t take that on right now.'' Manage your energy as well as your hours by doing demanding work when you are most alert.","keyPoints":["Balance means every important area gets enough attention, not equal time.","Burnout shows as exhaustion, negativity and falling effectiveness.","The Eisenhower matrix sorts tasks by urgency and importance.","Boundaries around rest, sleep and relationships make sustained effort possible."],"examples":[{"title":"Everything at once","scenario":"Nurin is a prefect, a debater, a tuition student and a netball player. She sleeps five hours, snaps at her family, and her marks are falling despite longer study hours.","takeaway":"Exhaustion, irritability and declining results are burnout signs. She drops one activity, fixes a bedtime and her marks recover. Doing less allowed her to do better."},{"title":"The scheduled quadrant","scenario":"Jia Hao always studies in a panic the night before tests. He begins scheduling two 45-minute revision blocks each week for subjects with no test coming up.","takeaway":"Giving time to important-but-not-urgent work reduces the number of emergencies. His evenings before tests become calmer and his sleep improves."}],"practicalTip":"List everything you need to do this week and place each item in one of the four Eisenhower boxes. Schedule two ''important but not urgent'' items in your calendar first, before anything else.","deeperInsight":"Parkinson''s law observes that work expands to fill the time available. If you give homework the whole evening, it takes the whole evening. Setting a clear finishing time often improves focus and frees time for rest, because the limit forces you to prioritise."}'::jsonb, '{"prompt":"Which area of your life is getting too little of you right now?","guidingQuestions":["What is the first sign that you are overloaded?","What are you saying yes to that you should say no to?","What activity restores your energy, and when did you last do it?"]}'::jsonb, '{"text":"When Salman al-Farisi saw his friend Abu ad-Darda'' neglecting rest and family for extra worship, he told him: your Lord has a right over you, your self has a right over you and your family has a right over you, so give each its due. The Prophet ﷺ confirmed, ''Salman has spoken the truth.'' The Quran teaches the same balance: seek the home of the Hereafter and do not forget your share of this world.","sources":["Sahih al-Bukhari 1968","Quran 28:77"]}'::jsonb, 3),
('vocational/financial-literacy', 'vocational', 'financial-literacy', 'Financial Literacy', '💰', 'Budgeting, saving and avoiding debt traps, so that money serves your goals.', '["Build a simple budget that separates needs, wants and savings.","Explain how compounding grows savings over time.","Recognise high-cost debt and common financial scams."]'::jsonb, 14, 20, '{"title":"Tell Your Money Where to Go","explanation":"Financial literacy is the ability to make informed decisions about earning, spending, saving and borrowing. It starts with one habit: knowing where your money goes. Track every ringgit for a month and you will almost certainly find spending you did not notice.\n\nA budget is simply a plan made in advance. A common starting guide is 50/30/20: about half of your income for needs (food, transport, fees), up to 30% for wants (entertainment, eating out, gadgets) and at least 20% for savings. Adjust the proportions to your situation, but keep the principle of paying yourself first: move savings aside the day money arrives, not from whatever is left.\n\nYour first savings goal is an emergency fund, ideally building towards three to six months of expenses, so that a phone repair or a lost job does not become a debt. After that, savings can grow through compounding, where returns earn returns. The ''rule of 72'' gives a quick estimate: divide 72 by the annual rate of return to find roughly how many years it takes money to double. Time is the key ingredient, which is why starting young matters more than starting big.\n\nBe careful with debt. ''Buy now, pay later'' schemes and credit cards make spending feel painless, and missed payments bring heavy charges. Be equally careful with promises of high, guaranteed returns. If an offer sounds too good to be true, it is. Check before you put money anywhere, and remember that in Malaysia, deposits in member banks are protected by PIDM up to RM250,000 per depositor per bank.","keyPoints":["Track your spending first; you cannot manage what you do not measure.","Budget in advance (for example 50/30/20) and save before you spend.","Build an emergency fund, then let compounding work over time.","Avoid high-cost debt and any offer of high ''guaranteed'' returns."],"examples":[{"title":"Where did RM300 go?","scenario":"Amirul receives RM300 a month in allowance and is always broke by week three. He records every purchase for a month and finds RM110 went on drinks and snacks bought in small amounts.","takeaway":"Small daily purchases were the leak. He sets a weekly limit for snacks and moves RM50 into savings on the first day of each month."},{"title":"Two savers","scenario":"Sara saves RM100 a month from age 18 to 28 and then stops. Daniel starts at 28 and saves RM100 a month until 48. At a steady 6% annual return, compounded monthly, Sara has about RM54,000 at 48 and Daniel about RM46,000, even though Sara put in RM12,000 and Daniel put in RM24,000.","takeaway":"Sara''s money had more time to compound. Starting early can matter more than how much you put in."}],"practicalTip":"For the next seven days, record every purchase, however small, in a notes app. At the end of the week, label each as a need or a want and add up each column.","deeperInsight":"Most poor money decisions are emotional. People spend to feel better, to keep up with friends or because a sale creates urgency. A simple defence is the 48-hour rule: for any non-essential purchase above an amount you set, wait two days. Most impulses pass."}'::jsonb, '{"prompt":"If you received RM500 today, what would you do with it? What does your answer reveal about your money habits?","guidingQuestions":["Do you know roughly how much you spent last week, and on what?","What are you saving for, and how much do you need?","What usually triggers your unplanned spending?"]}'::jsonb, '{"text":"The Quran describes the servants of the Most Merciful as those who, when they spend, are neither wasteful nor miserly but keep a just balance between the two. It permits trade and forbids riba (interest), and its longest verse instructs believers to write down debts. Wealth is a trust: earned lawfully, spent moderately, purified through zakat and shared through charity.","sources":["Quran 25:67","Quran 2:275","Quran 2:282"]}'::jsonb, 4),
('vocational/entrepreneurship', 'vocational', 'entrepreneurship', 'Entrepreneurship', '🚀', 'Spotting a real problem, testing a small solution, and understanding the basic numbers of a business.', '["Explain why a business starts with a customer''s problem, not with a product.","Describe what a minimum viable product (MVP) is and why it is used.","Calculate basic profit from revenue and costs."]'::jsonb, 14, 20, '{"title":"Solve a Problem, Then Sell","explanation":"Entrepreneurship is creating value for other people in a way that sustains itself. It can be a full business, a weekend side income or a social project. In every case it begins in the same place: a problem that real people have and would pay to solve. Beginners often start with a product they like and then search for buyers. Experienced founders start with the customer.\n\nSo begin by observing and asking. What do people around you complain about, queue for or do inefficiently? Talk to at least ten potential customers before spending money. Ask what they do about the problem now and what it costs them.\n\nThen test the idea as cheaply as possible. A minimum viable product, or MVP, is the simplest version that lets you learn whether people will actually pay: a pre-order form, a sample batch, a single service for one client. This build-measure-learn cycle, popularised by Eric Ries in The Lean Startup, replaces guessing with evidence. If nobody buys, you have lost little and learned a lot.\n\nKnow your numbers. Revenue is the money coming in. Costs include materials, packaging, delivery, fees and your time. Profit is revenue minus all costs. A product that sells well at a price below its true cost loses money faster the more you sell.\n\nFinally, do it properly: keep records, deliver what you promise, and when the business grows, register it with the Companies Commission of Malaysia (SSM).","keyPoints":["Start from a real problem that people will pay to solve.","Talk to potential customers before building or buying anything.","An MVP tests demand cheaply; learn and adjust.","Profit = revenue minus all costs, including your own time."],"examples":[{"title":"Pre-orders first","scenario":"Syazwani wants to sell homemade cookies for Hari Raya. Instead of buying ingredients for 200 jars, she posts photos of three sample flavours and takes pre-orders for one week. She receives 34 orders, mostly for one flavour.","takeaway":"The pre-order was her MVP. She buys ingredients for exactly what was ordered, drops the unpopular flavour and carries no unsold stock."},{"title":"The missing costs","scenario":"Raj sells phone cases at RM15 each and buys them at RM9, so he believes he earns RM6 a case. After adding RM2 packaging, RM3 average delivery subsidy and RM1 platform fee, his real profit is zero.","takeaway":"Listing every cost showed the true picture. He raises the price to RM19 and charges delivery separately."}],"practicalTip":"This week, write down five problems or frustrations you hear people mention. Choose one and ask three people how they deal with it now and whether they would pay for a better way.","deeperInsight":"Most new ventures fail because they build something nobody wants, not because of competition or lack of funds. The entrepreneurial skills that matter most are listening, testing assumptions and adapting, and these are valuable in any career, including for employees."}'::jsonb, '{"prompt":"What problem do you see around you every week that nobody seems to be solving well?","guidingQuestions":["Who has that problem, and how do they cope with it now?","What is the smallest, cheapest way you could test a solution?","What skills or resources do you already have that could help?"]}'::jsonb, '{"text":"The Prophet ﷺ was a merchant before prophethood, known as al-Amin, the trustworthy. He taught that buyer and seller keep the right to cancel until they part, and that if they are truthful and disclose defects their sale is blessed, while concealment and lying wipe out the blessing. The Quran commands trade by mutual consent and giving full measure. Honest business is a path to barakah.","sources":["Sahih al-Bukhari 2079","Sahih Muslim 1532","Quran 4:29","Quran 83:1-3"]}'::jsonb, 5),
('spiritual/presence', 'spiritual', 'presence', 'Presence', '🧘', 'Training your attention to stay with the present moment, using the breath and the senses as anchors.', '["Define mindfulness in plain language.","Explain why the mind wanders and why noticing it is the actual practice.","Carry out a three-minute breathing practice and a sensory grounding exercise."]'::jsonb, 10, 20, '{"title":"Coming Back Is the Practice","explanation":"Presence means your attention is where your body is. Most of the time it is not. Minds drift to replaying the past, rehearsing the future or checking a screen, and a wandering mind tends to be a more anxious one.\n\nMindfulness is the skill of bringing attention back. Jon Kabat-Zinn, who developed the Mindfulness-Based Stress Reduction programme, defines it as paying attention in a particular way: on purpose, in the present moment and without judgement. Notice the three parts. ''On purpose'' means you choose where attention goes. ''Present moment'' means what is actually happening now: this breath, this sound, this sensation. ''Without judgement'' means observing thoughts and feelings as passing events instead of criticising yourself for having them.\n\nThe basic practice is simple. Sit comfortably, breathe normally and rest your attention on the feeling of the breath at the nose or belly. Within seconds your mind will wander. This is not failure. The moment you notice that you have wandered and gently return to the breath is the exercise itself, like one repetition of a weight. Ten returns in three minutes is ten repetitions.\n\nYou can also anchor attention in the senses. The 5-4-3-2-1 exercise asks you to name five things you can see, four you can touch, three you can hear, two you can smell and one you can taste. It is especially useful when you feel anxious or overwhelmed.","keyPoints":["Mindfulness: attention on purpose, in the present moment, without judgement.","A wandering mind is normal; noticing and returning is the training.","The breath and the five senses are always available as anchors.","Short daily practice builds the skill better than occasional long sessions."],"examples":[{"title":"\"I can''t meditate\"","scenario":"Wei Ling tries a three-minute breathing exercise and gives up, saying her mind ''won''t stay still''. Her counsellor asks how many times she noticed it wandering. ''Maybe fifteen,'' she says.","takeaway":"Fifteen noticings means fifteen successful repetitions. The aim was never an empty mind. It was the returning."},{"title":"Before the exam paper","scenario":"Sitting in the exam hall with a racing heart, Aaron presses his feet into the floor and silently runs through 5-4-3-2-1, starting with five things he can see on his desk.","takeaway":"Directing attention to the senses pulled his mind out of ''what if I fail'' and back into the room, where he could begin the first question."}],"practicalTip":"Pick one daily activity, such as brushing your teeth or the first three bites of a meal, and do it with full attention this week: no phone, no planning, only the sensations. Add a three-minute breathing practice when you can.","deeperInsight":"Mindfulness is not relaxation, although calm often follows. Its purpose is awareness, including awareness of discomfort. When you can watch an urge or a worry rise and fade without immediately acting on it, you gain a choice you did not have before."}'::jsonb, '{"prompt":"Think about the last hour. How much of it were you actually present for?","guidingQuestions":["Where does your mind most often go when it wanders: the past, the future or a screen?","What daily activity do you do entirely on autopilot?","What did you notice when you tried the breathing practice?"]}'::jsonb, NULL, 1),
('spiritual/gratitude', 'spiritual', 'gratitude', 'Gratitude', '🌸', 'Why noticing what is good changes how you feel, and how to make gratitude a regular practice.', '["Explain why the mind notices problems more easily than good things.","Describe what research has found about regular gratitude practice.","Write a specific gratitude entry and a thank-you message."]'::jsonb, 10, 20, '{"title":"What You Notice Grows","explanation":"Gratitude is noticing and appreciating what is good in your life, and recognising that much of it comes from outside yourself: other people, nature, circumstances you did not create.\n\nIt does not come automatically. The human brain has a negativity bias. It reacts more strongly to threats and problems than to good events, because noticing danger kept our ancestors alive. One criticism can outweigh ten compliments. Left alone, attention drifts towards what is missing or wrong. Gratitude practice deliberately trains it the other way.\n\nThe evidence is encouraging. In a well-known set of studies by Robert Emmons and Michael McCullough, people who wrote down things they were grateful for each week reported feeling more optimistic and more satisfied with their lives than people who recorded hassles or neutral events. Later research links gratitude with better sleep and stronger relationships.\n\nTwo things make the practice work. Be specific: ''I''m grateful my sister saved me a seat and asked about my test'' affects you more than ''I''m grateful for family''. And keep it fresh: writing a few entries once or twice a week often works better than a daily list that turns into routine. Gratitude grows further when expressed. Telling someone exactly what they did and why it mattered benefits both of you. Gratitude does not mean pretending problems do not exist. It means seeing the whole picture, including the part that is going well.","keyPoints":["The brain''s negativity bias makes problems more noticeable than good things.","Regular gratitude writing is linked with more optimism and life satisfaction.","Specific entries work better than general ones.","Expressing thanks to others strengthens relationships."],"examples":[{"title":"Specific beats general","scenario":"Jasmine''s first journal entries read ''family, friends, food'' every night and soon feel empty. She switches to one detailed entry: ''Mum left dinner covered on the table when I came home late from training.''","takeaway":"The detail brought the moment back and with it the feeling. Specific entries make you relive the good event instead of listing a category."},{"title":"The thank-you message","scenario":"Daniel writes to a former teacher: ''In Form 2 you stayed back to explain algebra to me three times. I''m doing well in maths now and I wanted you to know that started with you.'' The teacher replies that she kept the message.","takeaway":"Expressed gratitude lifted both of them. Many people never learn the difference they made unless someone tells them."}],"practicalTip":"Twice this week, write three specific things you are grateful for and why each happened. Then send one short message thanking someone for something particular they did.","deeperInsight":"Gratitude and comparison pull in opposite directions. Social media constantly shows what others have, which trains attention on what you lack. A gratitude practice is partly a way of reclaiming your attention from that."}'::jsonb, '{"prompt":"What is one good thing in your life that you have stopped noticing because it is always there?","guidingQuestions":["Who has helped you in a way you have never properly thanked them for?","What went well today, and what made it possible?","When do you most often compare yourself with others?"]}'::jsonb, NULL, 2),
('spiritual/purpose', 'spiritual', 'purpose', 'Purpose', '🌟', 'Identifying your values and using them to give direction and meaning to everyday choices.', '["Explain the difference between values and goals.","Identify three to five personal core values.","Connect an ordinary daily task to something you care about."]'::jsonb, 12, 20, '{"title":"A Compass, Not a Map","explanation":"Purpose is the sense that your life is directed towards something that matters, to you and beyond you. It does not need to be grand. Purpose can be raising a family well, mastering a craft, serving a community or caring for one person. Research consistently links a sense of purpose with better well-being and greater persistence through difficulty.\n\nPurpose rests on values. A goal is a destination you can reach and tick off, such as passing an exam or buying a car. A value is a direction you keep travelling in, such as honesty, learning, kindness, courage or family. You never finish being kind. Goals without values feel hollow once achieved. Values give you a reason to set goals and a way to choose between them. In that sense values are a compass, and a compass is more useful than a map when the road changes.\n\nTo find your values, look at evidence. When have you felt most proud of yourself? What makes you angry when you see it violated? Whom do you admire, and for what? What would you do even if nobody praised you? Patterns in your answers point to what you care about.\n\nPsychiatrist Viktor Frankl, who survived the Nazi concentration camps, observed that people who had a reason to live could endure almost any hardship. He argued that meaning can be found in three ways: through what we create or do, through what we experience and whom we love, and through the attitude we take towards suffering we cannot avoid.","keyPoints":["Purpose is direction towards something that matters to you and beyond you.","Goals are destinations; values are directions.","Your proudest moments, your anger and your admiration reveal your values.","Meaning can be found in doing, in loving and in the attitude taken towards hardship."],"examples":[{"title":"Why am I studying this?","scenario":"Ravi finds Biology revision pointless until he connects it to a value. He wants to be a physiotherapist because he helped his grandfather recover from a stroke. ''I am learning how the body heals'' replaces ''I have to memorise Chapter 4.''","takeaway":"The task did not change. Linking it to something he cares about changed his motivation and persistence."},{"title":"The goal that felt empty","scenario":"Sophia works for a year to become head prefect. A month after achieving it she feels flat. Reflecting, she realises she values fairness and helping juniors, and begins a peer-support scheme.","takeaway":"The title was a goal, and reaching it ended the journey. Acting on her values gave her something to keep moving towards."}],"practicalTip":"Write down ten values that matter to you, then cross out five, then two more. For each of the three that remain, write one small action you could take this week that expresses it.","deeperInsight":"Purpose is usually built, not discovered in a flash. It tends to grow from engaging with the world: trying things, helping people and noticing what moves you. Waiting to ''find your purpose'' before acting has the order backwards."}'::jsonb, '{"prompt":"Describe a moment when you felt proud of how you acted, even though nobody praised you for it.","guidingQuestions":["Which value were you living by in that moment?","Whom do you admire most, and what quality in them draws you?","Which part of your current routine feels most meaningful, and which least?"]}'::jsonb, NULL, 3),
('spiritual/resilience', 'spiritual', 'resilience', 'Resilience', '🌊', 'Meeting difficulty with self-compassion and steady attention, so that you can return to balance.', '["Describe the three components of self-compassion.","Use the RAIN practice to work through a difficult emotion.","Explain why self-compassion supports motivation better than self-criticism."]'::jsonb, 12, 20, '{"title":"The Strength to Return","explanation":"Everyone is knocked off balance by failure, loss or disappointment. Inner resilience is the capacity to return to steadiness. The emotional wellness module covers the outer skills, such as support networks and realistic thinking. This pathway covers the inner stance: how you treat yourself when things go wrong.\n\nMany people respond to their own mistakes with harsh self-criticism, believing it keeps them disciplined. Research by psychologist Kristin Neff points the other way. People who treat themselves with compassion after a failure are more likely to take responsibility, try again and improve, because failure no longer feels so threatening that it must be avoided or denied.\n\nSelf-compassion has three parts. Self-kindness means speaking to yourself as you would to a good friend in the same situation. Common humanity means remembering that struggle and imperfection are part of being human, so you are not alone or uniquely flawed. Mindfulness means acknowledging the pain as it is, without suppressing it or being swept away.\n\nA practical tool for hard moments is RAIN, taught by meditation teacher Tara Brach. Recognise what you are feeling and name it. Allow it to be there for a moment without fighting it. Investigate with curiosity: where is it in your body, and what does it need? Nurture yourself with a kind phrase or gesture. Emotions that are allowed and understood tend to pass, while those that are fought tend to stay.","keyPoints":["Inner resilience is returning to steadiness after being knocked off balance.","Self-compassion: self-kindness, common humanity, mindfulness.","Self-compassion supports responsibility and persistence better than self-criticism.","RAIN: Recognise, Allow, Investigate, Nurture."],"examples":[{"title":"Two inner voices","scenario":"After forgetting her lines in a school play, Mira''s first thought is, ''You idiot, you ruined everything.'' She asks what she would say to a friend and tries again: ''That was painful. Everyone forgets lines sometimes. What would help for tomorrow''s show?''","takeaway":"The kinder voice did not excuse the mistake. It made it possible to think about improving instead of sinking into shame."},{"title":"RAIN after a rejection","scenario":"Ben is turned down for a scholarship. He sits quietly and works through RAIN: ''This is disappointment'' (Recognise). ''It is okay to feel this'' (Allow). ''It''s heavy in my chest, and I think I''m afraid I''ve let my parents down'' (Investigate). ''I worked hard. One result does not define me'' (Nurture).","takeaway":"Ten minutes of honest attention settled him enough to talk to his parents and look at other options that evening."}],"practicalTip":"The next time you make a mistake, put a hand on your chest, take one slow breath and say to yourself what you would say to a close friend in the same situation. Notice how your body responds.","deeperInsight":"Self-compassion is often mistaken for self-pity or making excuses. Self-pity says ''poor me, this only happens to me''. Self-compassion says ''this is hard, it is hard for many people, and I can care for myself through it''. The first isolates you and the second connects you."}'::jsonb, '{"prompt":"How do you usually talk to yourself after a mistake? Would you speak that way to a friend?","guidingQuestions":["What difficult feeling have you been pushing away recently?","What kind phrase could you say to yourself in hard moments?","Who models calm recovery from setbacks in your life, and what do they do?"]}'::jsonb, NULL, 4),
('spiritual-islamic/dhikr-and-remembrance', 'spiritual-islamic', 'dhikr-and-remembrance', 'Dhikr & Remembrance', '📿', 'What dhikr is, why it gives the heart rest, and how to build it into the day.', '["Explain the meaning of dhikr and its place in the Quran and Sunnah.","Recite and understand several authentic forms of dhikr.","Plan fixed moments of dhikr through the day."]'::jsonb, 12, 20, '{"title":"Hearts Find Rest in Remembrance","explanation":"Dhikr means remembering Allah: with the tongue, with the heart and through actions done in awareness of Him. It is among the easiest acts of worship, since it needs no wudu'', no particular place and no set time, and it is among the most rewarded. Allah says, ''So remember Me; I will remember you'', and ''Surely in the remembrance of Allah do hearts find rest.''\n\nThe Prophet ﷺ compared the person who remembers his Lord and the one who does not to the living and the dead. A heart without dhikr is alive in body but starved in spirit.\n\nThe Sunnah gives specific words. Subhanallah (Glory be to Allah) declares Him free of any imperfection. Alhamdulillah (All praise is for Allah) is thanks and praise. Allahu akbar (Allah is greatest) puts every worry in proportion. La ilaha illallah (There is no god but Allah) is the foundation of faith. The Prophet ﷺ said that two phrases are light on the tongue, heavy on the scale and beloved to the Most Merciful: Subhanallahi wa bihamdihi, Subhanallahil-''Azim. After each obligatory prayer he taught saying Subhanallah, Alhamdulillah and Allahu akbar thirty-three times each, completing the hundred with La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir.\n\nThe best dhikr joins tongue and heart. Understand what you say, and say it attentively. A small amount done every day is better than a large amount done rarely.","keyPoints":["Dhikr is remembrance of Allah with tongue, heart and action.","Allah promises to remember those who remember Him, and that hearts find rest in it.","Authentic forms include tasbih, tahmid, takbir and tahlil, especially after each prayer.","Presence of heart and consistency matter more than quantity."],"examples":[{"title":"Anchored to the prayer","scenario":"Luqman used to stand up immediately after the salam. He begins staying seated for two minutes after each prayer to complete the thirty-three tasbih, tahmid and takbir on his fingers.","takeaway":"Attaching dhikr to something he already does five times a day made it automatic. The prayers themselves began to feel less rushed."},{"title":"The commute","scenario":"Hannah spends forty minutes on the LRT each day scrolling. She keeps the first ten minutes of the journey for Subhanallahi wa bihamdihi and istighfar, with her phone in her bag.","takeaway":"Dead time became worship. She notices she arrives at class calmer than before."}],"practicalTip":"Choose one fixed anchor this week: the dhikr after each obligatory prayer. Learn the meaning of each phrase before you start, and count on your fingers, as the Prophet ﷺ was seen doing.","deeperInsight":"In a hadith qudsi, Allah says: ''I am as My servant thinks of Me, and I am with him when he remembers Me. If he remembers Me within himself, I remember him within Myself.'' Dhikr is therefore a relationship, not a formula: the servant''s remembrance is answered by Allah''s own.","sources":["Quran 2:152","Quran 13:28","Quran 33:41-42","Sahih al-Bukhari 6407 (the living and the dead)","Sahih al-Bukhari 6406; Sahih Muslim 2694 (two phrases light on the tongue)","Sahih Muslim 597 (dhikr after prayer)","Sahih al-Bukhari 7405; Sahih Muslim 2675 (hadith qudsi)","Sunan Abi Dawud 1502 (counting tasbih on the fingers; graded sahih by al-Albani)"]}'::jsonb, '{"prompt":"At which moments in your day is your heart most forgetful of Allah, and at which is it most aware?","guidingQuestions":["Which phrase of dhikr do you say most often without thinking about its meaning?","What waiting time in your day could become time for remembrance?","How do you feel after a few minutes of attentive dhikr compared with a few minutes of scrolling?"]}'::jsonb, NULL, 1),
('spiritual-islamic/dua-and-supplication', 'spiritual-islamic', 'dua-and-supplication', 'Du''a & Supplication', '🤲', 'Asking Allah directly: why du''a is worship, how to make it and how it is answered.', '["Explain why du''a is itself an act of worship.","Apply the etiquette of du''a taught in the Sunnah.","Identify times when du''a is especially likely to be accepted."]'::jsonb, 12, 20, '{"title":"He Is Near","explanation":"Du''a is calling upon Allah: asking Him, thanking Him and speaking to Him about your needs. It requires no intermediary. Allah says, ''When My servants ask you about Me, I am near. I respond to the call of the caller when he calls upon Me'', and ''Call upon Me; I will respond to you.'' The Prophet ﷺ said, ''Du''a is worship'', because asking Allah is an admission that He alone controls all things and that you need Him.\n\nThe Sunnah teaches an etiquette. Begin by praising Allah and sending blessings on the Prophet ﷺ. Raise your hands. Ask with humility, sincerity and a present heart, certain that Allah hears. Ask for the good of this world and the next, and be specific. Acknowledge your sins and ask forgiveness. Ask repeatedly, and do not ask for anything sinful or for the cutting of family ties.\n\nSome times carry special hope of acceptance: the last third of the night, during sujud, and between the adhan and the iqamah.\n\nA sincere du''a is never wasted, but the answer is not always what or when we expect. The Prophet ﷺ taught that a person''s du''a is answered so long as he is not hasty, saying, ''I prayed and was not answered'', and giving up. Allah gives in the way He knows is best. The most frequent du''a of the Prophet ﷺ was: Rabbana atina fid-dunya hasanah, wa fil-akhirati hasanah, wa qina ''adhaban-nar.","keyPoints":["Du''a is worship: it expresses need of Allah and trust in Him.","Allah is near and responds to the caller directly.","Etiquette: praise Allah, send salawat, raise the hands, ask with certainty and persistence.","Do not be hasty; Allah answers in the way and time that is best."],"examples":[{"title":"Du''a with effort","scenario":"Before SPM, Aisyah makes du''a in sujud each night for understanding and success, and studies according to a plan each day.","takeaway":"Du''a and effort work together. She asks Allah for the outcome while doing what is in her power, which is what the Prophet ﷺ practised."},{"title":"\"My du''a wasn''t answered\"","scenario":"Yusuf prays for months to be accepted to a certain university and is rejected. He is tempted to stop making du''a. His father reminds him that the Prophet ﷺ warned against haste. A year later, at a different university, Yusuf finds a course and mentors that suit him far better.","takeaway":"The answer came in a form he did not ask for. Continuing to ask, and trusting Allah''s choice, is part of the worship."}],"practicalTip":"Tonight, in the sujud of a sunnah or night prayer, ask Allah for one thing for your Hereafter, one for this world, and one for someone else. Then learn the du''a ''Rabbana atina...'' with its meaning if you have not yet.","deeperInsight":"The Prophet ﷺ taught that the du''a made for a fellow Muslim in his absence is answered, and an angel says, ''Amin, and for you the same.'' Praying for others is thus one of the surest ways of being prayed for.","sources":["Quran 2:186","Quran 40:60","Quran 2:201","Sunan Abi Dawud 1479; Jami'' at-Tirmidhi 2969 (du''a is worship; sahih)","Jami'' at-Tirmidhi 3477 (beginning with praise and salawat; sahih)","Sunan Abi Dawud 1488 (raising the hands; sahih)","Jami'' at-Tirmidhi 212 (between the adhan and the iqamah; sahih)","Sahih al-Bukhari 6340; Sahih Muslim 2735 (not being hasty)","Sahih al-Bukhari 1145; Sahih Muslim 758 (the last third of the night)","Sahih Muslim 482 (du''a in sujud)","Sahih al-Bukhari 6389; Sahih Muslim 2690 (the Prophet''s most frequent du''a)","Sahih Muslim 2732 (du''a for one''s brother in his absence)"]}'::jsonb, '{"prompt":"What is one thing you have been carrying alone that you have not yet asked Allah about?","guidingQuestions":["When you make du''a, is your heart present, or is it a routine of the tongue?","Has a du''a of yours been answered in a way you did not expect?","Who could you make du''a for today without them knowing?"]}'::jsonb, NULL, 2),
('spiritual-islamic/tawakkul-and-trust-in-allah', 'spiritual-islamic', 'tawakkul-and-trust-in-allah', 'Tawakkul & Trust in Allah', '🌿', 'Relying on Allah with the heart while taking every lawful means with the limbs.', '["Define tawakkul and distinguish it from passivity.","Explain the relationship between effort, trust and outcome.","Apply tawakkul to a current worry."]'::jsonb, 12, 20, '{"title":"Tie Your Camel, Then Trust","explanation":"Tawakkul is the heart''s reliance on Allah to bring benefit and repel harm, together with taking the lawful means available. It has two halves, and removing either one changes it into something else. Effort without trust becomes anxiety and self-reliance. ''Trust'' without effort is not tawakkul but negligence.\n\nThe Prophet ﷺ made this clear when a man asked whether he should tie his camel and rely on Allah, or leave it loose and rely on Allah. He replied, ''Tie it and rely on Allah.'' He also said that if you relied on Allah as He deserves, He would provide for you as He provides for the birds: they go out in the morning hungry and return in the evening full. Notice that the birds leave the nest. They do not wait for food to arrive.\n\nThe Hijrah shows the balance at its highest level. The Prophet ﷺ planned carefully: he left at an unexpected time, hid in the cave of Thawr for three nights, arranged for news and provisions, and hired a skilled guide who took an unusual route. He did everything a human being could do. Yet when their pursuers stood at the mouth of the cave and Abu Bakr (RA) feared for him, he said, ''What do you think of two, when Allah is their third?''\n\nThe Quran sets the order: ''When you have decided, then rely upon Allah. Indeed, Allah loves those who rely upon Him.'' Consult, plan, decide and act. Then leave the outcome to Allah and be content with what He decrees, for ''whoever relies upon Allah, He is sufficient for him.''","keyPoints":["Tawakkul is the heart''s reliance on Allah combined with taking the means.","Effort belongs to the limbs; trust belongs to the heart; the outcome belongs to Allah.","The Hijrah joined careful planning with complete trust.","After doing your part, be content with what Allah decrees."],"examples":[{"title":"The night before results","scenario":"Imran cannot sleep before his exam results. His mother asks, ''Did you study as well as you could?'' He did. ''Then your part is finished. The result is with Allah, and He does not waste effort.''","takeaway":"Separating what was his responsibility (effort) from what was never his (outcome) let him rest. That is tawakkul in practice."},{"title":"\"Allah will provide\"","scenario":"Zaid has stopped applying for jobs and says he is ''leaving it to Allah''. A friend reminds him of the camel and the birds. Zaid sends five applications that week and makes du''a after each one.","takeaway":"Trust without action misreads tawakkul. Taking the means is an act of obedience, and relying on Allah for the result is an act of faith."}],"practicalTip":"Take one current worry and draw two columns: ''My part'' and ''Allah''s decree''. Write what you can do in the first, do the first item today, and say ''Hasbunallahu wa ni''mal-wakil'' (Allah is sufficient for us, and He is the best disposer of affairs) for the second.","deeperInsight":"Ibn ''Abbas (RA) reported that ''Hasbunallahu wa ni''mal-wakil'' was said by Ibrahim عليه السلام when he was thrown into the fire, and by Muhammad ﷺ when people said, ''The enemy has gathered against you, so fear them.'' In both cases the danger was real and the means were exhausted. Tawakkul shows its full strength exactly where human ability ends.","sources":["Quran 3:159","Quran 65:3","Quran 9:40","Quran 3:173","Jami'' at-Tirmidhi 2517 (tie it and rely on Allah; hasan)","Jami'' at-Tirmidhi 2344 (the birds; hasan sahih)","Sahih al-Bukhari 3905 (the planning of the Hijrah)","Sahih al-Bukhari 3653; Sahih Muslim 2381 (Allah is their third)","Sahih al-Bukhari 4563 (Hasbunallahu wa ni''mal-wakil)"]}'::jsonb, '{"prompt":"What are you most anxious about at the moment? Which part of it is yours to do, and which belongs to Allah?","guidingQuestions":["Do you lean more towards worrying as if everything depends on you, or towards waiting without acting?","When has something you feared turned out to hold good for you?","What would change in your day if you truly believed Allah is sufficient for you?"]}'::jsonb, NULL, 3),
('spiritual-islamic/gratitude-shukr', 'spiritual-islamic', 'gratitude-shukr', 'Gratitude (Shukr)', '💛', 'Thanking Allah with the heart, the tongue and the limbs, and the promise of increase.', '["Explain the three dimensions of shukr.","Relate shukr to Allah''s promise of increase in the Quran.","Practise gratitude towards Allah and towards people."]'::jsonb, 12, 20, '{"title":"Shall I Not Be a Grateful Servant?","explanation":"Shukr is recognising that every blessing comes from Allah and responding to it properly. Scholars such as Ibn al-Qayyim describe three dimensions. With the heart, you acknowledge that the blessing is from Allah and not simply from your own cleverness. With the tongue, you praise Him, saying Alhamdulillah. With the limbs, you use the blessing in obedience to Him and not in disobedience. Health is thanked by worship and service, wealth by charity, knowledge by teaching and acting on it.\n\nAllah attaches a promise to gratitude: ''If you are grateful, I will surely increase you.'' He also reminds us that gratitude benefits the grateful person: ''Whoever is grateful is grateful only for his own good.'' And He tells us how far His blessings exceed our counting: ''If you tried to count the favours of Allah, you could never number them.''\n\nThe Prophet ﷺ lived this. He stood so long in night prayer that his feet swelled. When asked why, since Allah had forgiven him, he replied, ''Shall I not be a grateful servant?'' He taught that Allah is pleased with a servant who eats a meal and praises Him for it, or takes a drink and praises Him for it.\n\nTwo teachings keep gratitude alive. Look at those who have less than you in worldly matters, not those who have more, so that you do not belittle Allah''s favours. And thank people, for whoever does not thank people has not thanked Allah.","keyPoints":["Shukr is with the heart (acknowledging), the tongue (praising) and the limbs (obeying).","Allah promises increase to the grateful.","The Prophet ﷺ expressed gratitude through extra worship.","Look at those with less, and thank the people through whom blessings reach you."],"examples":[{"title":"Gratitude of the limbs","scenario":"Fatimah scores well in her exams. She says Alhamdulillah, prays two rak''at, and then offers to tutor two classmates who are struggling in the subject she is best at.","takeaway":"She thanked Allah with heart, tongue and action. Using a blessing to benefit others is the fullest form of shukr."},{"title":"The old phone","scenario":"Amir is unhappy that his phone is two models behind his friends''. While helping at a food-bank distribution, he meets a boy his age who shares one phone with four siblings for online classes.","takeaway":"The Prophet''s instruction to look at those with less changed how Amir saw what he already had. Nothing in his pocket had changed."}],"practicalTip":"Before sleeping tonight, name three specific blessings from today and say Alhamdulillah for each. Then choose one and decide how you will use it in obedience to Allah tomorrow.","deeperInsight":"Allah says, ''Work, O family of Dawud, in gratitude. And few of My servants are grateful.'' The verse ties gratitude to work, not to words alone, and it warns that true shukr is rare. Gratitude is also owed in hardship, since the believer knows that what Allah withholds may itself be a mercy.","sources":["Quran 14:7","Quran 31:12","Quran 16:18","Quran 34:13","Sahih al-Bukhari 4836; Sahih Muslim 2819 (Shall I not be a grateful servant?)","Sahih Muslim 2734 (praising Allah after eating and drinking)","Sahih Muslim 2963 (look at those below you)","Sunan Abi Dawud 4811; Jami'' at-Tirmidhi 1954 (thanking people; sahih)"]}'::jsonb, '{"prompt":"Which blessing do you use every day and almost never thank Allah for?","guidingQuestions":["In which area of life do you compare yourself with those who have more?","How could you use one of your strengths this week as an act of gratitude?","Which person has Allah sent good to you through, whom you have not thanked?"]}'::jsonb, NULL, 4),
('spiritual-islamic/prayer-and-devotion', 'spiritual-islamic', 'prayer-and-devotion', 'Prayer & Devotion', '🕌', 'The five daily prayers as the believer''s direct connection with Allah, and how to pray with presence.', '["Explain the place of salah among the pillars of Islam.","Describe what khushu'' means and practical ways to develop it.","Commit to guarding the five prayers on time."]'::jsonb, 14, 20, '{"title":"Five Meetings a Day","explanation":"Salah is the second pillar of Islam and the first deed a servant will be questioned about on the Day of Judgement. It was prescribed for the believers at fixed times, and Allah states its purpose: ''Establish prayer for My remembrance.'' Five times a day, whatever you are doing, you stop and stand before your Lord.\n\nThe Prophet ﷺ asked his Companions to imagine a river at someone''s door in which he bathes five times a day. Would any dirt remain on him? They said no. He said that this is the likeness of the five prayers, by which Allah wipes away sins. The Quran adds that prayer restrains from indecency and wrongdoing. A prayer that is truly established changes how a person behaves between prayers.\n\nThe quality that gives prayer its life is khushu'': humility and presence of heart. Allah says, ''Successful indeed are the believers, those who are humble in their prayers.'' The Prophet ﷺ taught a man who had prayed hurriedly to go back and repeat it, and to be still in each position, in bowing, standing, prostration and sitting, before moving to the next. Practical steps help: make wudu'' carefully, pray on time and not at the last minute, put the phone away, learn the meaning of al-Fatihah and what you recite, and move calmly.\n\nThe summit is ihsan, which the Prophet ﷺ defined as worshipping Allah as though you see Him, and though you do not see Him, He surely sees you. He ﷺ would say to Bilal (RA), ''Give us rest with it'', meaning the prayer. For him it was a relief, not a burden.","keyPoints":["Salah is a pillar of Islam and the first deed to be accounted for.","The five prayers cleanse sins like bathing five times a day in a river.","Khushu'' means humility and presence of heart, supported by calm, unhurried movement.","Ihsan: worship Allah as though you see Him, knowing that He sees you."],"examples":[{"title":"From rushing to resting","scenario":"Hafiz used to finish Zuhur in two minutes during school break. After learning the meaning of al-Fatihah, he slows down, pauses after each verse and stays still in ruku'' and sujud. The prayer now takes five minutes.","takeaway":"Understanding the words and observing stillness in each position turned a routine into a real pause in his day."},{"title":"Guarding Subuh","scenario":"Maryam keeps missing Subuh. She moves her bedtime earlier, sets her alarm across the room, makes the intention before sleeping and asks her sister to wake her. Within two weeks she is praying it on time most days.","takeaway":"She joined intention and du''a with practical means. Small, steady changes built a habit that willpower alone had not."}],"practicalTip":"Choose one prayer today and pray it as if it were your last: careful wudu'', phone in another room, and a full, still pause in every position. Learn the meaning of one phrase you recite that you did not understand before.","deeperInsight":"The Prophet ﷺ said that the deeds most beloved to Allah are those done most consistently, even if they are small. A person who guards the five obligatory prayers every day, without fail, is following this principle more closely than one who prays long voluntary prayers occasionally and neglects the obligatory ones.","sources":["Quran 20:14","Quran 29:45","Quran 23:1-2","Quran 4:103","Sahih al-Bukhari 8; Sahih Muslim 16 (the five pillars)","Jami'' at-Tirmidhi 413 (the first deed to be accounted for; sahih)","Sahih al-Bukhari 528; Sahih Muslim 667 (the river)","Sahih al-Bukhari 757; Sahih Muslim 397 (stillness in each position)","Sahih Muslim 8 (ihsan, the hadith of Jibril)","Sunan Abi Dawud 4985 (Give us rest with it; sahih)","Sahih al-Bukhari 6464; Sahih Muslim 783 (consistent deeds)"]}'::jsonb, '{"prompt":"Which of your five prayers is strongest, and which is weakest? What makes the difference?","guidingQuestions":["What most often distracts you during prayer?","Do you understand the meaning of what you recite in each rak''ah?","What single practical change would help you guard your weakest prayer?"]}'::jsonb, NULL, 5)
INSERT INTO public.module_quiz_questions (id, topic_id, sort_order, question, options, correct_index, explanation)
VALUES
('physical/nutrition-and-diet#1', 'physical/nutrition-and-diet', 1, 'In the Malaysian Healthy Plate (Suku-Suku Separuh), what should fill half of your plate?', '["Vegetables and fruit","Rice, noodles or other grains","Meat, fish, eggs or tofu","Soup and gravy"]'::jsonb, 0, 'Half the plate is vegetables and fruit. Grains take one quarter and protein takes the other quarter.'),
('physical/nutrition-and-diet#2', 'physical/nutrition-and-diet', 2, 'A canned drink lists 28 g of sugar. About how many teaspoons is that?', '["2 teaspoons","4 teaspoons","7 teaspoons","14 teaspoons"]'::jsonb, 2, 'One teaspoon of sugar is about 4 g, so 28 g divided by 4 is 7 teaspoons, which is more than the ideal daily limit of about 6.'),
('physical/nutrition-and-diet#3', 'physical/nutrition-and-diet', 3, 'Which nutrient is mainly responsible for building and repairing body tissue such as muscle?', '["Carbohydrate","Fibre","Protein","Water"]'::jsonb, 2, 'Protein supplies the building blocks for muscle, skin and blood. Carbohydrate is mainly for energy, and fibre supports digestion.'),
('physical/exercise-and-fitness#1', 'physical/exercise-and-fitness', 1, 'According to WHO guidelines, how much moderate-to-vigorous activity should a 15-year-old average each day?', '["At least 15 minutes","At least 30 minutes","At least 60 minutes","At least 120 minutes"]'::jsonb, 2, 'For ages 5 to 17 the WHO recommends an average of at least 60 minutes a day of moderate-to-vigorous activity.'),
('physical/exercise-and-fitness#2', 'physical/exercise-and-fitness', 2, 'During a jog you can speak in full sentences but could not sing. What intensity is this?', '["Moderate intensity","Vigorous intensity","Resting level","Maximum effort"]'::jsonb, 0, 'The talk test: able to talk but not sing means moderate intensity. At vigorous intensity you can only manage a few words at a time.'),
('physical/exercise-and-fitness#3', 'physical/exercise-and-fitness', 3, 'Which weekly plan is most likely to build lasting fitness?', '["One long three-hour session every second week","Hard training every single day with no rest days","Four 20-minute sessions across the week","Only stretching, with no other activity"]'::jsonb, 2, 'The body adapts to regular demand. Short sessions repeated through the week build fitness and are easier to keep up than rare, exhausting ones.'),
('physical/sleep-hygiene#1', 'physical/sleep-hygiene', 1, 'How much sleep is recommended each night for a 16-year-old?', '["5 to 6 hours","6 to 7 hours","8 to 10 hours","12 to 14 hours"]'::jsonb, 2, 'Sleep medicine bodies recommend 8 to 10 hours for ages 13 to 18. Young adults need 7 to 9.'),
('physical/sleep-hygiene#2', 'physical/sleep-hygiene', 2, 'Why does using a bright phone screen in bed make it harder to fall asleep?', '["It raises body temperature by several degrees","It uses up the brain''s supply of oxygen","It increases caffeine levels","It delays the release of melatonin"]'::jsonb, 3, 'Light at night signals ''daytime'' to the body clock and delays melatonin, the hormone that brings on sleepiness.'),
('physical/sleep-hygiene#3', 'physical/sleep-hygiene', 3, 'Which single habit does the most to keep your body clock steady?', '["Waking at about the same time every day","Napping for two hours each afternoon","Sleeping in late on weekends to catch up","Drinking coffee right after dinner"]'::jsonb, 0, 'A consistent wake time anchors the circadian rhythm. Large weekend shifts and late caffeine both disturb it.'),
('physical/medical-health#1', 'physical/medical-health', 1, 'A friend has had a cold for two days and wants to take leftover antibiotics. What is the best response?', '["Take a double dose so that the cold clears up faster","Take them only until the fever stops","Skip them; antibiotics do not treat colds","Share them with others who feel unwell"]'::jsonb, 2, 'Colds are caused by viruses, which antibiotics cannot treat. Unnecessary use also contributes to antibiotic resistance.'),
('physical/medical-health#2', 'physical/medical-health', 2, 'Which situation needs emergency help immediately rather than a routine appointment?', '["A mild sore throat that started this morning","Chest pain with difficulty breathing","Slightly dry skin","Feeling sleepy after a late night"]'::jsonb, 1, 'Chest pain with breathing difficulty is a warning sign that should never wait. In Malaysia, call 999.'),
('physical/medical-health#3', 'physical/medical-health', 3, 'Which feature makes online health advice more trustworthy?', '["It has millions of views and thousands of shares","It promises a guaranteed quick cure","It is shared by a celebrity you like","It names a qualified health body"]'::jsonb, 3, 'Reliable advice identifies a qualified source, such as the Ministry of Health or a registered professional. Popularity and big promises are not evidence.'),
('physical/personal-safety#1', 'physical/personal-safety', 1, 'If you feel you are being followed while walking, what is the safest first move?', '["Stop, turn around and confront the person directly","Take a quiet shortcut to get home faster","Head for a busy, well-lit place and call someone","Keep walking and ignore the feeling"]'::jsonb, 2, 'Moving towards people and light and alerting someone reduces risk. Confrontation and isolated shortcuts increase it.'),
('physical/personal-safety#2', 'physical/personal-safety', 2, 'A caller says they are from your bank and urgently need the TAC code sent to your phone. What should you do?', '["Hang up and call the bank yourself","Read out the code quickly before it expires","Give only half of the code","Ask them to send a second code"]'::jsonb, 0, 'Banks never ask for TAC codes or passwords. End the call and contact the bank through its official number. If money has been lost, call 997.'),
('physical/personal-safety#3', 'physical/personal-safety', 3, 'Which statement about personal boundaries is correct?', '["A boundary only counts if the other person agrees to it","You may say no without giving a reason","Setting a boundary is rude to friends and family","Boundaries are only needed with strangers"]'::jsonb, 1, 'A boundary is your decision about what you accept. It does not need the other person''s approval, and it applies to people you know as well as strangers.'),
('social/communication-skills#1', 'social/communication-skills', 1, 'Which response is the best example of active listening?', '["\"So you felt embarrassed in front of everyone?\"","\"That happened to me too, but honestly mine was so much worse.\"","\"You should just ignore it and move on.\"","\"Anyway, did you see the match last night?\""]'::jsonb, 0, 'Reflecting back the speaker''s meaning and feeling shows you understood. The other replies shift attention to yourself, give unrequested advice or change the subject.'),
('social/communication-skills#2', 'social/communication-skills', 2, 'Which sentence is a well-formed ''I'' statement?', '["\"I feel that you are always careless and never think about anyone else.\"","\"I can''t believe you did that again.\"","\"I know you don''t care about my time.\"","\"I feel worried when plans change late. Can you tell me earlier?\""]'::jsonb, 3, 'A real ''I'' statement names the situation, your own feeling and a request. Starting a criticism with the word ''I'' does not make it one.'),
('social/communication-skills#3', 'social/communication-skills', 3, 'A friend says "It''s okay, I''m not angry" while avoiding eye contact and speaking coldly. What will most people believe?', '["The words, because they are clear","The tone and body language","Neither, because the signals cancel out","The words, because friends are honest"]'::jsonb, 1, 'When verbal and non-verbal messages conflict, listeners usually trust the non-verbal signals.'),
('social/relationship-building#1', 'social/relationship-building', 1, 'According to this lesson, what builds trust most reliably?', '["One expensive gift","Agreeing with everything the other person says","Spending every free hour together","Small promises kept consistently over time"]'::jsonb, 3, 'Trust accumulates through many small, dependable actions. Gifts and constant agreement do not replace reliability.'),
('social/relationship-building#2', 'social/relationship-building', 2, 'Which behaviour is a warning sign of an unhealthy relationship?', '["They encourage you to spend time with your family","They disagree with you politely","They get angry when you see other friends","They ask how your day was"]'::jsonb, 2, 'Trying to cut you off from other people is a form of control. Healthy relationships leave room for your other connections.'),
('social/relationship-building#3', 'social/relationship-building', 3, 'In a healthy relationship, what should happen when you say "no" to something?', '["Your decision is respected","You are ignored until you finally change your mind","You are made to feel guilty","You must always give a detailed reason"]'::jsonb, 0, 'Being able to refuse without punishment is a basic sign of respect and safety in any relationship.'),
('social/community-involvement#1', 'social/community-involvement', 1, 'What is the best way to choose where to volunteer?', '["Wait until a large, well-known organisation invites you to join","Find where your interests, skills and a real need overlap","Pick whatever looks best on a certificate","Choose the activity that needs the least effort"]'::jsonb, 1, 'Service that matches what you care about and can do, and that meets a real need, is the kind you are most likely to continue.'),
('social/community-involvement#2', 'social/community-involvement', 2, 'What does the Malaysian term gotong-royong describe?', '["A yearly competition between neighbouring housing areas","A government tax on communities","Working together voluntarily for a shared benefit","A traditional solo craft"]'::jsonb, 2, 'Gotong-royong is communal, voluntary cooperation, such as neighbours cleaning a shared area together.'),
('social/community-involvement#3', 'social/community-involvement', 3, 'Which is a benefit volunteers commonly gain for themselves?', '["Guaranteed top results in every school examination","Automatic payment","Less need for sleep","A stronger sense of belonging and purpose"]'::jsonb, 3, 'Regular volunteering is linked with belonging, purpose, friendships and practical skills. It does not guarantee grades or pay.'),
('social/networking-and-etiquette#1', 'social/networking-and-etiquette', 1, 'What is the healthiest way to think about networking?', '["Building real relationships where you give as well as receive","Collecting as many contacts as possible","Only talking to senior people who can offer you a job or a reference","Impressing people by talking about yourself"]'::jsonb, 0, 'Lasting professional relationships are built on real interest and mutual help, not on collecting or using contacts.'),
('social/networking-and-etiquette#2', 'social/networking-and-etiquette', 2, 'Research on ''weak ties'' suggests new opportunities often come from whom?', '["Only your closest friends","Acquaintances in different circles","Strangers you have never met or spoken to in any way","Only your immediate family"]'::jsonb, 1, 'Acquaintances connect you to different groups and so carry information that your close circle does not already have.'),
('social/networking-and-etiquette#3', 'social/networking-and-etiquette', 3, 'Which message to a teacher shows good digital etiquette?', '["\"cikgu can extend or not\"","A two-minute voice note sent at midnight","\"Good afternoon Cikgu, this is Adam from 4 Bestari. May I submit the essay tomorrow morning? Thank you.\"","\"URGENT!!! reply now\""]'::jsonb, 2, 'It greets the teacher, identifies the sender, makes a clear request and says thank you, at a reasonable hour.'),
('social/conflict-resolution#1', 'social/conflict-resolution', 1, 'Two friends each insist on a different restaurant. One wants somewhere cheap; the other wants somewhere with vegetarian food. What are ''cheap'' and ''vegetarian options'' in this conflict?', '["Positions","Insults","Compromises","Interests"]'::jsonb, 3, 'The named restaurants are positions. The reasons behind them, low cost and suitable food, are interests, and one place may satisfy both.'),
('social/conflict-resolution#2', 'social/conflict-resolution', 2, 'Which conflict style aims for a solution that meets the main needs of both sides?', '["Collaborating","Competing","Avoiding","Accommodating"]'::jsonb, 0, 'Collaborating means working together to satisfy both sides'' key interests. Compromising, by contrast, has each side give something up.'),
('social/conflict-resolution#3', 'social/conflict-resolution', 3, 'You are very angry in the middle of an argument. What is the most effective next step?', '["Say everything you feel immediately, while it is still fresh in your mind","Post about it online to get support","Ask for a short break and promise to come back to it","Give in completely so it ends"]'::jsonb, 2, 'A brief cooling-off period, with a commitment to come back, lets both people think clearly and prevents words that are later regretted.'),
('intellectual/lifelong-learning#1', 'intellectual/lifelong-learning', 1, 'What does neuroplasticity mean?', '["The brain stops developing completely once childhood is over","The brain''s connections change with practice","Intelligence is fixed at birth","Only talented people can learn hard subjects"]'::jsonb, 1, 'Neuroplasticity is the brain''s lifelong ability to strengthen and reorganise its connections in response to what you practise.'),
('intellectual/lifelong-learning#2', 'intellectual/lifelong-learning', 2, 'Which statement reflects a growth mindset?', '["\"I failed, so I''m not smart enough for this.\"","\"If I have to try hard, it means I have no talent.\"","\"I''ll avoid hard questions so I don''t look stupid.\"","\"I haven''t mastered this yet, so I need a different strategy.\""]'::jsonb, 3, 'A growth mindset sees ability as something that develops with effort and better strategies, and treats difficulty as part of learning.'),
('intellectual/lifelong-learning#3', 'intellectual/lifelong-learning', 3, 'What is the central step of the Feynman technique?', '["Explaining the concept simply and finding where you get stuck","Highlighting the textbook in several different colours to mark the key ideas","Memorising the definition word for word","Reading the chapter three times quickly"]'::jsonb, 0, 'Explaining simply forces real understanding and shows you exactly which parts you need to revisit.'),
('intellectual/critical-thinking#1', 'intellectual/critical-thinking', 1, 'What does the "S" in the SIFT method tell you to do first?', '["Share it with a friend to get their view","Search for similar posts","Stop before reacting or sharing","Save it for later"]'::jsonb, 2, 'SIFT begins with Stop: pause before you react, then investigate the source, find better coverage and trace the claim.'),
('intellectual/critical-thinking#2', 'intellectual/critical-thinking', 2, 'You strongly support a football club and immediately believe a rumour that a rival cheated, without checking. Which bias is at work?', '["Hindsight bias","Confirmation bias","Optimism bias","Anchoring bias"]'::jsonb, 1, 'Confirmation bias is the tendency to accept information that fits what you already believe or want to be true.'),
('intellectual/critical-thinking#3', 'intellectual/critical-thinking', 3, 'Students who eat breakfast tend to get higher grades. What can you correctly conclude from this alone?', '["Eating breakfast is definitely the cause of the higher grades","Higher grades cause students to eat breakfast","The data must be false","The two are linked, but other factors may explain it"]'::jsonb, 3, 'A correlation shows two things occur together. Other factors, such as sleep or home routine, might explain both, so causation is not proven.'),
('intellectual/creativity-and-innovation#1', 'intellectual/creativity-and-innovation', 1, 'During the divergent thinking phase, what should you do?', '["Pick the single best idea immediately","Reject any idea that seems unrealistic or too expensive to try","List as many ideas as possible without judging them","Wait for inspiration before writing anything"]'::jsonb, 2, 'Divergent thinking is about quantity and variety. Judging and selecting belongs to the later, convergent phase.'),
('intellectual/creativity-and-innovation#2', 'intellectual/creativity-and-innovation', 2, 'A student turns old school uniforms into tote bags. Which SCAMPER prompt does this best match?', '["Put to another use","Eliminate","Reverse","Substitute"]'::jsonb, 0, 'The uniforms are given a new purpose, which is the ''Put to another use'' prompt.'),
('intellectual/creativity-and-innovation#3', 'intellectual/creativity-and-innovation', 3, 'Why do innovators build rough early versions of an idea?', '["Because the quality of the final product does not really matter","To learn from real feedback before investing heavily","To avoid ever showing the idea to anyone","Because first versions are usually perfect"]'::jsonb, 1, 'A quick, rough version lets you test assumptions cheaply and improve the idea based on how real people respond.'),
('intellectual/cognitive-skills#1', 'intellectual/cognitive-skills', 1, 'What actually happens when you try to do two demanding mental tasks at the same time?', '["Your brain switches between them, losing time and accuracy","Your brain processes both tasks at full quality, as if each were done alone","Your working memory doubles in size","You remember both tasks better"]'::jsonb, 0, 'The brain alternates between demanding tasks, and every switch has a cost in speed and accuracy.'),
('intellectual/cognitive-skills#2', 'intellectual/cognitive-skills', 2, 'Which activity is an example of retrieval practice?', '["Highlighting the key sentences in three different colours","Re-reading the chapter slowly","Copying the textbook neatly","Closing your notes and writing what you remember"]'::jsonb, 3, 'Retrieval practice means recalling information from memory without looking, which strengthens the memory more than reviewing it passively.'),
('intellectual/cognitive-skills#3', 'intellectual/cognitive-skills', 3, 'You have four hours to prepare for a test in two weeks. Which plan uses spaced repetition?', '["One four-hour session the night before","Four one-hour sessions spread across the two weeks","One four-hour session today, then nothing","Two hours tonight and two hours tomorrow, then nothing"]'::jsonb, 1, 'Spacing the same total time across increasing intervals gives better long-term retention than massing it together.'),
('intellectual/cultural-awareness#1', 'intellectual/cultural-awareness', 1, 'Which statement is a stereotype rather than a generalisation?', '["\"Many families in this community celebrate that festival.\"","\"Greetings often differ between cultures.\"","\"Some cultures tend to communicate more indirectly.\"","\"All people from that group are bad at sports.\""]'::jsonb, 3, 'A stereotype applies a fixed judgement to every member of a group. The other statements describe tendencies and leave room for individual differences.'),
('intellectual/cultural-awareness#2', 'intellectual/cultural-awareness', 2, 'In a high-context communication style, how is meaning mostly carried?', '["Only by the literal words that are spoken, with nothing implied","Through written contracts","Through tone, relationship and what is left unsaid","By speaking as loudly as possible"]'::jsonb, 2, 'High-context communication relies heavily on shared understanding, tone and implication, while low-context communication spells things out.'),
('intellectual/cultural-awareness#3', 'intellectual/cultural-awareness', 3, 'You are invited to a celebration from a culture you do not know well. What is the most respectful approach?', '["Ask the host politely what you should know","Decline the invitation, to avoid making a mistake","Behave exactly as you would at home","Point out which customs seem strange to you"]'::jsonb, 0, 'Respectful curiosity, asking in advance and observing, shows care and helps you take part appropriately.'),
('emotional/emotional-intelligence#1', 'emotional/emotional-intelligence', 1, 'Which of these is one of the four areas of emotional intelligence?', '["Memory speed","Self-awareness","Physical strength","Verbal fluency"]'::jsonb, 1, 'The four areas are self-awareness, self-management, social awareness and relationship management.'),
('emotional/emotional-intelligence#2', 'emotional/emotional-intelligence', 2, 'What does research suggest happens when you put a strong feeling into words?', '["The feeling becomes more intense and much harder to control","Nothing changes at all","The brain''s alarm response becomes less active","You forget what caused the feeling"]'::jsonb, 2, 'Labelling an emotion is associated with reduced activity in the brain''s threat-detection centre, which helps you calm down and think.'),
('emotional/emotional-intelligence#3', 'emotional/emotional-intelligence', 3, 'A friend cancels plans at the last minute and you feel hurt. Which response shows emotional intelligence?', '["Sending an angry message straight away so they know how you feel","Pretending you never cared about the plan","Ignoring the friend for a week","Noticing the hurt, then asking calmly what happened"]'::jsonb, 3, 'EI means recognising your feeling and choosing a response that helps the situation, instead of reacting or suppressing.'),
('emotional/stress-management#1', 'emotional/stress-management', 1, 'What is the purpose of the body''s fight-or-flight response?', '["To prepare the body to deal with a challenge or danger","To make you fall asleep quickly whenever a situation becomes dangerous","To slow down your heart rate","To improve digestion"]'::jsonb, 0, 'Adrenaline and cortisol raise heart rate, breathing and muscle tension so the body is ready to act.'),
('emotional/stress-management#2', 'emotional/stress-management', 2, 'Which describes the box breathing technique?', '["Breathe as fast as possible for one minute","Inhale 4, hold 4, exhale 4, hold 4","Hold your breath for as long as you can","Inhale through the mouth only"]'::jsonb, 1, 'Box breathing uses four equal counts: in, hold, out, hold. The slow, steady rhythm activates the body''s calming system.'),
('emotional/stress-management#3', 'emotional/stress-management', 3, 'You feel overwhelmed by many worries. According to this lesson, what is a useful first step?', '["Try not to think about any of them","Stay up all night so that you can deal with every single one of them at once","Write them down and sort what you can control from what you cannot","Wait until the stress goes away by itself"]'::jsonb, 2, 'Listing and sorting your worries makes them manageable and shows where a small action is possible.'),
('emotional/coping-mechanisms#1', 'emotional/coping-mechanisms', 1, 'Your grandmother has passed away and you are grieving. Which type of coping fits this situation best?', '["Problem-focused coping, because the cause can be fixed with a good plan","Avoidance, because thinking about it is painful","No coping is needed","Emotion-focused coping, because the loss cannot be undone"]'::jsonb, 3, 'When a situation cannot be changed, healthy coping means caring for the feeling: talking, remembering, praying, resting and being with others.'),
('emotional/coping-mechanisms#2', 'emotional/coping-mechanisms', 2, 'Which is a sign that a coping habit is unhealthy?', '["It gives quick relief but leaves you worse off later","It involves talking to someone about what happened and how you feel","It takes some effort to do","It helps you understand your feelings"]'::jsonb, 0, 'Unhealthy coping trades short-term relief for a longer-term cost, such as a bigger problem, guilt or harm to health.'),
('emotional/coping-mechanisms#3', 'emotional/coping-mechanisms', 3, 'A friend says they have felt hopeless for a month and sometimes think about hurting themselves. What should you do?', '["Promise to keep it completely secret","Tell them to stop being dramatic","Encourage them to talk to a trusted adult or a helpline, and stay with them","Avoid them until they feel better"]'::jsonb, 2, 'Thoughts of self-harm need support from a trusted adult or professional. Listen, stay with them and help them reach out. Do not keep it secret.'),
('emotional/building-resilience#1', 'emotional/building-resilience', 1, 'Which statement best describes resilience?', '["Never feeling sad, stressed or disappointed about anything","Adapting and recovering after difficulty","Hiding your feelings from everyone","Handling every problem alone"]'::jsonb, 1, 'Resilient people still feel hard emotions. Resilience is the capacity to recover and adapt, usually with support from others.'),
('emotional/building-resilience#2', 'emotional/building-resilience', 2, 'According to research, which factor contributes most strongly to resilience?', '["Having a high IQ","Never experiencing failure","Being naturally cheerful","Supportive relationships"]'::jsonb, 3, 'Having at least one stable, supportive relationship is the factor most consistently linked with resilience.'),
('emotional/building-resilience#3', 'emotional/building-resilience', 3, 'After failing one test, a student thinks, "I''m a failure at everything." Which of the three Ps is this?', '["Pervasive: one setback spreads to all of life","Practical: making a step-by-step plan to improve next time","Patient: waiting for things to improve","Positive: seeing the good side"]'::jsonb, 0, 'Believing that one failure affects everything is the ''pervasive'' pattern. A more accurate view limits the setback to the area where it happened.'),
('emotional/positive-psychology#1', 'emotional/positive-psychology', 1, 'What does the "R" in the PERMA model stand for?', '["Responsibility","Rewards","Relationships","Resilience"]'::jsonb, 2, 'PERMA stands for Positive emotion, Engagement, Relationships, Meaning and Accomplishment.'),
('emotional/positive-psychology#2', 'emotional/positive-psychology', 2, 'Which statement best describes positive psychology?', '["The belief that you should never feel any negative emotions","The scientific study of what helps people do well","A method of ignoring your problems","The idea that success always brings happiness"]'::jsonb, 1, 'Positive psychology studies well-being scientifically. It does not deny difficult emotions or problems.'),
('emotional/positive-psychology#3', 'emotional/positive-psychology', 3, 'In the ''three good things'' exercise, what do you write each night?', '["Three goals you want to achieve in the next year","Three mistakes you made today","Three people who annoyed you","Three things that went well and why"]'::jsonb, 3, 'Recording three things that went well, and the reason for each, trains attention towards the good that is already present.'),
('environmental/sustainable-living#1', 'environmental/sustainable-living', 1, 'In the waste hierarchy, which action has the greatest positive impact?', '["Recycling everything you use","Buying biodegradable packaging","Refusing what you do not need","Sorting rubbish into colours"]'::jsonb, 2, 'Not creating the waste in the first place is the most effective step. Recycling is the last resort for what remains.'),
('environmental/sustainable-living#2', 'environmental/sustainable-living', 2, 'Why is recycling placed last in the waste hierarchy?', '["It still uses energy, and not everything collected is recycled","It is illegal in most places","It only works for glass","It creates more waste than sending everything straight to a landfill"]'::jsonb, 0, 'Recycling is useful but requires energy, transport and processing, and a share of collected material is never recycled.'),
('environmental/sustainable-living#3', 'environmental/sustainable-living', 3, 'Which habit reduces food waste most directly?', '["Eating faster","Taking only the amount you will actually eat","Buying food in the largest packs available at the shop","Using paper plates"]'::jsonb, 1, 'Most household food waste comes from taking, cooking or buying more than is eaten. Right-sized portions prevent it at the source.'),
('environmental/conservation-efforts#1', 'environmental/conservation-efforts', 1, 'What does the term biodiversity refer to?', '["The variety of living things and ecosystems in an area","The total number of people living in a country or region","The amount of rainfall in a forest","The size of a national park"]'::jsonb, 0, 'Biodiversity is the variety of life at every level, from genes and species to whole ecosystems.'),
('environmental/conservation-efforts#2', 'environmental/conservation-efforts', 2, 'Why are mangrove forests valuable to coastal communities?', '["They make sea water clean enough for people to drink safely","They increase the temperature of the sea","They stop all rain from falling inland","They protect coasts from storms and shelter young fish"]'::jsonb, 3, 'Mangroves buffer waves and storm surges, hold sediment and act as nurseries for many fish and crustaceans.'),
('environmental/conservation-efforts#3', 'environmental/conservation-efforts', 3, 'Which everyday choice most directly reduces the illegal wildlife trade?', '["Watching wildlife documentaries","Refusing to buy wildlife products or wild-caught exotic pets","Visiting more shopping malls","Using more paper bags"]'::jsonb, 1, 'Illegal trade exists because of demand. Refusing to buy, and reporting sellers, removes the incentive.'),
('environmental/appreciation-of-nature#1', 'environmental/appreciation-of-nature', 1, 'According to the 2019 study mentioned in this lesson, about how much weekly time in nature is linked with better health and well-being?', '["At least 10 minutes","At least 30 minutes","At least 120 minutes","At least 500 minutes"]'::jsonb, 2, 'People who spent 120 minutes or more a week in nature were more likely to report good health and well-being, however the time was divided.'),
('environmental/appreciation-of-nature#2', 'environmental/appreciation-of-nature', 2, 'According to attention restoration theory, why does a walk in a park refresh your mind?', '["The air in a park contains far more oxygen than the air in a classroom","Walking burns away stress hormones instantly","Natural scenes hold attention gently, letting directed attention rest","Parks are always quieter than homes"]'::jsonb, 2, 'Demanding tasks drain directed attention. Nature engages you effortlessly, which gives that system time to recover.'),
('environmental/appreciation-of-nature#3', 'environmental/appreciation-of-nature', 3, 'Which activity best matches the idea of ''forest bathing'' (shinrin-yoku)?', '["Walking slowly among trees, paying attention with all your senses","Running a timed race through a forest","Swimming in a forest river","Photographing trees for social media"]'::jsonb, 0, 'Shinrin-yoku is slow, mindful time among trees, taking in the sights, sounds, smells and textures.'),
('environmental/healthy-personal-space#1', 'environmental/healthy-personal-space', 1, 'Why does studying on your bed often make both studying and sleeping harder?', '["Beds are too soft to rest books and a laptop on properly","The brain stops linking the bed with sleep alone","Bedrooms have too little oxygen","Mattresses block wireless signals"]'::jsonb, 1, 'The brain associates places with activities. Mixing work and rest in one spot weakens the bed''s signal for sleep and encourages drowsiness while studying.'),
('environmental/healthy-personal-space#2', 'environmental/healthy-personal-space', 2, 'Which bedroom conditions are best for sleep?', '["Warm, bright and lively","Hot and humid with the television on","Cool, dark and quiet","Brightly lit with windows sealed"]'::jsonb, 2, 'Most people sleep best in a room that is cool, dark and quiet.'),
('environmental/healthy-personal-space#3', 'environmental/healthy-personal-space', 3, 'What is the main advantage of a five-minute daily reset over an occasional big clean-up?', '["It means you never need to clean the room thoroughly again","It requires expensive storage boxes","It only works in large rooms","Small regular effort stops mess from building up"]'::jsonb, 3, 'A short daily routine keeps disorder from accumulating, so the space stays usable with very little effort.'),
('environmental/community-green-initiatives#1', 'environmental/community-green-initiatives', 1, 'In Malaysia''s recycling colour system, which bin is for paper?', '["Blue","Orange","Brown","Red"]'::jsonb, 0, 'Blue bins are for paper, brown for glass, and orange for plastic, aluminium and other metals.'),
('environmental/community-green-initiatives#2', 'environmental/community-green-initiatives', 2, 'What is the best first step when starting a community green project?', '["Design a logo and order matching T-shirts for the team","Identify a specific, visible local problem","Wait for a large sponsor","Plan a nationwide campaign"]'::jsonb, 1, 'A clear, local problem gives the project focus and makes it easy for others to see why it matters.'),
('environmental/community-green-initiatives#3', 'environmental/community-green-initiatives', 3, 'Why is a small monthly clean-up usually more effective than one very large event?', '["Large events are not allowed by most local councils","Small groups collect more rubbish per hour","Repeated action builds habits and lasting results","Monthly events do not need volunteers"]'::jsonb, 2, 'Consistency maintains the improvement, grows the group over time and makes care for the place part of community life.'),
('vocational/career-exploration#1', 'vocational/career-exploration', 1, 'According to this lesson, what is the most useful way to think about choosing a career at your age?', '["As one permanent decision that you must get exactly right","As something to leave entirely to your parents","As a choice based only on salary","As a series of experiments towards a good next step"]'::jsonb, 3, 'Careers develop through exploration and adjustment. The aim is a well-informed next step, not a final answer.'),
('vocational/career-exploration#2', 'vocational/career-exploration', 2, 'Someone who enjoys teaching, counselling and looking after others scores highest in which RIASEC type?', '["Social","Realistic","Conventional","Investigative"]'::jsonb, 0, 'The Social type is drawn to helping, teaching and caring roles.'),
('vocational/career-exploration#3', 'vocational/career-exploration', 3, 'What is an informational interview?', '["A formal interview to be hired for a job","A written test of your general knowledge","A conversation with someone in a job to learn what the work is really like","An interview with a journalist"]'::jsonb, 2, 'It is a short, informal conversation in which you ask a working professional about their job, path and advice.'),
('vocational/skill-development#1', 'vocational/skill-development', 1, 'Which of these is a transferable (soft) skill?', '["Using accounting software","Working well in a team","Welding steel pipes","Programming in Python"]'::jsonb, 1, 'Teamwork applies in every field. The other three are technical skills tied to particular kinds of work.'),
('vocational/skill-development#2', 'vocational/skill-development', 2, 'Which activity is the best example of deliberate practice?', '["Repeating the parts you already do well","Practising for many hours without any particular goal","Watching experts without trying it yourself","Working on a specific weak point with feedback"]'::jsonb, 3, 'Deliberate practice targets a specific weakness at the edge of your ability and uses feedback to adjust.'),
('vocational/skill-development#3', 'vocational/skill-development', 3, 'What does a ''T-shaped'' set of skills mean?', '["Deep skill in one area plus broad knowledge of others","Knowing a tiny amount about every subject without depth in any","Being skilled only in technical subjects","Having exactly two unrelated skills"]'::jsonb, 0, 'The vertical bar of the T is depth in one field, and the horizontal bar is breadth across related areas.'),
('vocational/work-life-balance#1', 'vocational/work-life-balance', 1, 'Which set of signs describes burnout?', '["High energy, enthusiasm and strong results","Hunger, thirst and restlessness","Exhaustion, negativity towards work and reduced effectiveness","Boredom, curiosity and excitement"]'::jsonb, 2, 'The WHO describes burnout through three dimensions: exhaustion, mental distance or negativity, and reduced effectiveness.'),
('vocational/work-life-balance#2', 'vocational/work-life-balance', 2, 'In the Eisenhower matrix, what should you do with tasks that are important but not urgent?', '["Drop them","Schedule them","Do them only when they become emergencies","Hand them to someone else"]'::jsonb, 1, 'Important-but-not-urgent tasks, such as early revision, exercise and relationships, should be planned into your week before they become crises.'),
('vocational/work-life-balance#3', 'vocational/work-life-balance', 3, 'Which statement about work-life balance is accurate?', '["It means spending exactly the same number of hours on every activity each day","Rest should only happen after all work is finished","Saying no to new commitments shows weakness","It means each important area of life gets enough attention over time"]'::jsonb, 3, 'Balance is about sufficiency across your important areas over a period of time, not identical hours each day.'),
('vocational/financial-literacy#1', 'vocational/financial-literacy', 1, 'In the 50/30/20 budgeting guide, what is the 20% for?', '["Entertainment","Food and transport","Savings","Gifts for friends"]'::jsonb, 2, 'The guide suggests about 50% for needs, up to 30% for wants and at least 20% for savings.'),
('vocational/financial-literacy#2', 'vocational/financial-literacy', 2, 'Using the rule of 72, about how long does money take to double at a 6% annual return?', '["6 years","12 years","36 years","72 years"]'::jsonb, 1, '72 divided by 6 is 12, so money roughly doubles in about 12 years at 6% a year.'),
('vocational/financial-literacy#3', 'vocational/financial-literacy', 3, 'An online group promises a "guaranteed 20% return every month" if you join quickly. What is the wisest response?', '["Invest a small amount first to test whether it is real","Treat it as a likely scam and do not invest","Borrow money so you can invest more","Recruit friends first to earn a bonus"]'::jsonb, 1, 'High guaranteed returns combined with pressure to act fast are classic signs of a scam. No legitimate investment guarantees returns like that.'),
('vocational/entrepreneurship#1', 'vocational/entrepreneurship', 1, 'According to this lesson, where should a new business idea begin?', '["With a real problem that customers want solved","With a product that you personally like and want to make","With a company logo and name","With a large bank loan"]'::jsonb, 0, 'A business creates value by solving a problem people have and will pay to fix. Products and branding follow from that.'),
('vocational/entrepreneurship#2', 'vocational/entrepreneurship', 2, 'What is the purpose of a minimum viable product (MVP)?', '["To launch a perfect, finished product on the very first day","To avoid ever speaking to customers","To impress investors with features","To test cheaply whether people will actually pay"]'::jsonb, 3, 'An MVP is the simplest version that lets you learn from real customer behaviour before investing heavily.'),
('vocational/entrepreneurship#3', 'vocational/entrepreneurship', 3, 'You sell 20 keychains at RM10 each. Materials cost RM4 per keychain and you pay RM30 in total for a market table. What is your profit?', '["RM90","RM120","RM170","RM200"]'::jsonb, 0, 'Revenue is 20 × RM10 = RM200. Costs are 20 × RM4 = RM80 plus RM30 = RM110. Profit is RM200 − RM110 = RM90.'),
('spiritual/presence#1', 'spiritual/presence', 1, 'During breathing practice, you notice your mind has wandered to tomorrow''s homework. What should you do?', '["Stop, because the practice has failed","Criticise yourself for losing focus","Force your mind to become completely blank","Gently return your attention to the breath"]'::jsonb, 3, 'Noticing and gently returning is the practice itself. Wandering is expected, and self-criticism is not part of it.'),
('spiritual/presence#2', 'spiritual/presence', 2, 'Which is NOT part of Jon Kabat-Zinn''s definition of mindfulness?', '["Paying attention on purpose","Staying in the present moment","Emptying the mind of all thoughts","Observing what arises without judgement"]'::jsonb, 2, 'Mindfulness does not require an empty mind. It means attending on purpose, in the present, without judging what you notice.'),
('spiritual/presence#3', 'spiritual/presence', 3, 'In the 5-4-3-2-1 grounding exercise, what do you begin with?', '["Five things you can see","Five deep breaths","Five things you are worried about","Five things you are grateful for"]'::jsonb, 0, 'The exercise moves through the senses: five things seen, four touched, three heard, two smelled, one tasted.'),
('spiritual/gratitude#1', 'spiritual/gratitude', 1, 'What is the ''negativity bias''?', '["A habit of always expecting good outcomes","The brain''s tendency to react more strongly to bad events than good ones","A dislike of other people''s success","A medical condition that causes sadness"]'::jsonb, 1, 'The brain gives more weight to threats and problems than to positive events, which is why gratitude takes deliberate practice.'),
('spiritual/gratitude#2', 'spiritual/gratitude', 2, 'Which gratitude journal entry is likely to have the strongest effect?', '["\"I am grateful for everything.\"","\"Friends.\"","\"My friend walked me home in the rain and shared her umbrella.\"","\"Nothing bad happened today.\""]'::jsonb, 2, 'Specific, detailed entries bring the experience back to mind and produce more feeling than general categories.'),
('spiritual/gratitude#3', 'spiritual/gratitude', 3, 'What did Emmons and McCullough find among people who regularly recorded things they were grateful for?', '["They became much less aware of the problems in their lives","They earned higher incomes","They needed fewer friends","They reported more optimism and life satisfaction"]'::jsonb, 3, 'Compared with people who listed hassles or neutral events, the gratitude group reported feeling more optimistic and more satisfied with life.'),
('spiritual/purpose#1', 'spiritual/purpose', 1, 'Which of these is a value rather than a goal?', '["Being honest","Scoring an A in the trial exam","Saving RM1,000 by December","Finishing a 10 km run"]'::jsonb, 0, 'Honesty is a direction you keep living by and never ''complete''. The others are goals that can be achieved and ticked off.'),
('spiritual/purpose#2', 'spiritual/purpose', 2, 'According to Viktor Frankl, which is one way people can find meaning?', '["By avoiding all difficulty","Through the attitude they take towards unavoidable suffering","By comparing themselves with others","By owning more possessions"]'::jsonb, 1, 'Frankl described three sources of meaning: what we create or do, what we experience and love, and the attitude we take towards suffering we cannot change.'),
('spiritual/purpose#3', 'spiritual/purpose', 3, 'Which question is most useful for identifying your personal values?', '["\"What is the highest-paying job?\"","\"What do most of my classmates want?\"","\"When have I felt most proud of how I acted?\"","\"What is trending this week?\""]'::jsonb, 2, 'Moments of real pride reveal what you care about. Income, popularity and trends tell you about other people''s priorities.'),
('spiritual/resilience#1', 'spiritual/resilience', 1, 'Which of these is one of the three components of self-compassion described by Kristin Neff?', '["Self-improvement","Competition","Perfectionism","Common humanity"]'::jsonb, 3, 'The three components are self-kindness, common humanity and mindfulness.'),
('spiritual/resilience#2', 'spiritual/resilience', 2, 'What does the ''A'' in the RAIN practice stand for?', '["Allow","Avoid","Analyse","Achieve"]'::jsonb, 0, 'RAIN stands for Recognise, Allow, Investigate, Nurture. ''Allow'' means letting the feeling be present without fighting it.'),
('spiritual/resilience#3', 'spiritual/resilience', 3, 'According to research, how does self-compassion after a failure affect people?', '["It makes them lazy and careless","It stops them from caring about results","It makes them more likely to take responsibility and try again","It causes them to blame others"]'::jsonb, 2, 'When failure feels less threatening, people are more able to admit mistakes, learn from them and keep trying.'),
('spiritual-islamic/dhikr-and-remembrance#1', 'spiritual-islamic/dhikr-and-remembrance', 1, 'What does Allah promise in Surah al-Baqarah 2:152 to those who remember Him?', '["That they will never face any hardship","That He will remember them","That they will become wealthy","That they will not need to pray"]'::jsonb, 1, '''So remember Me; I will remember you. And be grateful to Me and do not deny Me.'' (Quran 2:152)'),
('spiritual-islamic/dhikr-and-remembrance#2', 'spiritual-islamic/dhikr-and-remembrance', 2, 'Which two phrases did the Prophet ﷺ describe as light on the tongue, heavy on the scale and beloved to the Most Merciful?', '["Bismillah and Alhamdulillah","Astaghfirullah and Insha''Allah","Allahu akbar and Masha''Allah","Subhanallahi wa bihamdihi, Subhanallahil-''Azim"]'::jsonb, 3, 'Narrated by Abu Hurairah (RA) in Sahih al-Bukhari and Sahih Muslim.'),
('spiritual-islamic/dhikr-and-remembrance#3', 'spiritual-islamic/dhikr-and-remembrance', 3, 'The Prophet ﷺ compared the one who remembers Allah and the one who does not to what?', '["The living and the dead","The rich and the poor","The traveller and the resident","The young and the old"]'::jsonb, 0, '''The example of the one who remembers his Lord and the one who does not is like that of the living and the dead.'' (Sahih al-Bukhari 6407)'),
('spiritual-islamic/dua-and-supplication#1', 'spiritual-islamic/dua-and-supplication', 1, 'According to the Prophet ﷺ, what is du''a?', '["A cultural custom","A last resort after all else fails","Worship","Only for scholars"]'::jsonb, 2, 'The Prophet ﷺ said, ''Du''a is worship'', then recited: ''Your Lord says: Call upon Me; I will respond to you.'' (Abu Dawud, at-Tirmidhi; Quran 40:60)'),
('spiritual-islamic/dua-and-supplication#2', 'spiritual-islamic/dua-and-supplication', 2, 'In which position is a servant closest to his Lord, and so encouraged to make much du''a?', '["While standing","In sujud (prostration)","While sitting between the two prostrations","While bowing in ruku''"]'::jsonb, 1, '''The closest a servant is to his Lord is while he is prostrating, so make much du''a.'' (Sahih Muslim 482)'),
('spiritual-islamic/dua-and-supplication#3', 'spiritual-islamic/dua-and-supplication', 3, 'What did the Prophet ﷺ warn against regarding du''a?', '["Asking for worldly needs","Making du''a in one''s own language","Repeating the same request","Being hasty and saying, \"I prayed but was not answered\""]'::jsonb, 3, 'A person''s du''a is answered so long as he is not hasty and does not give up. (Sahih al-Bukhari 6340; Sahih Muslim 2735)'),
('spiritual-islamic/tawakkul-and-trust-in-allah#1', 'spiritual-islamic/tawakkul-and-trust-in-allah', 1, 'A man asked whether to tie his camel or leave it and rely on Allah. What did the Prophet ﷺ answer?', '["\"Leave it; Allah will guard it.\"","\"Sell the camel.\"","\"Tie it and rely on Allah.\"","\"Ask someone else to watch it.\""]'::jsonb, 2, 'Reported by Anas ibn Malik (RA) in Jami'' at-Tirmidhi. Taking the means and trusting Allah go together.'),
('spiritual-islamic/tawakkul-and-trust-in-allah#2', 'spiritual-islamic/tawakkul-and-trust-in-allah', 2, 'Which statement correctly describes tawakkul?', '["Relying on Allah in the heart while taking lawful means","Doing nothing and waiting for results","Relying only on your own effort, planning and ability to control results","Trusting Allah only when all plans have failed"]'::jsonb, 0, 'Tawakkul joins effort with the limbs and reliance in the heart. Abandoning the means is negligence, and relying on effort alone is self-reliance.'),
('spiritual-islamic/tawakkul-and-trust-in-allah#3', 'spiritual-islamic/tawakkul-and-trust-in-allah', 3, 'According to Quran 3:159, when should a believer place their reliance upon Allah?', '["Instead of consulting anyone","After consulting and reaching a decision","Only when in danger","Before thinking about the matter"]'::jsonb, 1, 'The verse instructs consultation, then: ''When you have decided, then rely upon Allah. Indeed, Allah loves those who rely upon Him.'''),
('spiritual-islamic/gratitude-shukr#1', 'spiritual-islamic/gratitude-shukr', 1, 'What does Allah promise in Surah Ibrahim 14:7 to those who are grateful?', '["That He will surely increase them","That they will never be tested","That they will be praised by people","That their past will be forgotten"]'::jsonb, 0, '''And when your Lord proclaimed: If you are grateful, I will surely increase you; but if you are ungrateful, My punishment is severe.'' (Quran 14:7)'),
('spiritual-islamic/gratitude-shukr#2', 'spiritual-islamic/gratitude-shukr', 2, 'What did the Prophet ﷺ say when asked why he prayed at night until his feet swelled?', '["\"I fear the people''s criticism.\"","\"I have many sins to erase.\"","\"It is obligatory upon me.\"","\"Shall I not be a grateful servant?\""]'::jsonb, 3, 'He ﷺ expressed gratitude to Allah through worship. (Sahih al-Bukhari 4836; Sahih Muslim 2819)'),
('spiritual-islamic/gratitude-shukr#3', 'spiritual-islamic/gratitude-shukr', 3, 'Which of these is an example of shukr with the limbs?', '["Feeling pleased with a gift","Using your health and time in obedience to Allah","Saying Alhamdulillah","Knowing in your heart that every blessing comes from Allah"]'::jsonb, 1, 'Shukr with the limbs means using blessings in ways that please Allah. Acknowledging is shukr of the heart, and saying Alhamdulillah is shukr of the tongue.'),
('spiritual-islamic/prayer-and-devotion#1', 'spiritual-islamic/prayer-and-devotion', 1, 'To what did the Prophet ﷺ compare the five daily prayers?', '["A long journey through the desert","A shield carried into battle","A tree with five branches","A river at one''s door in which one bathes five times a day"]'::jsonb, 3, 'Just as no dirt would remain after bathing five times daily, Allah wipes away sins through the five prayers. (Sahih al-Bukhari 528; Sahih Muslim 667)'),
('spiritual-islamic/prayer-and-devotion#2', 'spiritual-islamic/prayer-and-devotion', 2, 'How did the Prophet ﷺ define ihsan in the hadith of Jibril?', '["To give charity every day","To pray only when you feel ready","To worship Allah as though you see Him, for though you do not see Him, He sees you","To memorise the entire Quran"]'::jsonb, 2, 'This definition comes from the hadith of Jibril عليه السلام, narrated by ''Umar ibn al-Khattab (RA) in Sahih Muslim.'),
('spiritual-islamic/prayer-and-devotion#3', 'spiritual-islamic/prayer-and-devotion', 3, 'According to Quran 23:1-2, which quality in prayer marks the successful believers?', '["Humility and presence of heart (khushu'')","Praying as quickly as possible so as to finish early","Praying only in congregation","Reciting in a loud voice"]'::jsonb, 0, '''Successful indeed are the believers, those who are humble (khashi''un) in their prayers.'' (Quran 23:1-2)');
